import SwiftUI

/// Image card with two-layer scroll parallax, press-to-lift, and a slotted liquid glass caption.
///
/// The caption is a glass panel inset over the bottom of the picture, and the trailing glyph a round glass bubble
/// resting joined to it, so a liquid neck holds the two together as one surface.
///
/// - Parameters:
///   - image: The picture to show, scaled to fill.
///   - eyebrow: Optional small uppercase line above the title, for a category or date.
///   - title: Title drawn in the caption.
///   - metadata: Optional short facts shown in a dot-separated row under the title.
///   - trailingSymbol: Optional SF Symbol drawn in a glass bubble joined to the caption's trailing end, for example "arrow.up.right".
///   - height: Card height.
///   - parallax: How far the image drifts, as a fraction of `height` on each side. The caption drifts at a third of that. 0 disables the effect.
///   - cornerRadius: Corner radius of the card.
///   - style: Caption treatment and colors. `.standard` is a neutral glass panel whose ink follows the appearance; `.scrim` puts white text over a darkened bottom edge.
///   - action: Optional tap handler. When set, the card lifts on press and reads as a button.
public struct ParallaxCard: View {
    /// How the caption sits on the picture, and its colors.
    public struct Style: Sendable {
        /// Caption treatment.
        public enum Caption: Sendable {
            /// An inset liquid glass panel that drifts over the picture.
            case block
            /// White text over a bottom scrim, for busy photos that should stay edge to edge. The trailing bubble is
            /// dark glass.
            case scrim
        }

        /// Caption treatment.
        public var caption: Caption
        /// The glass tint of the caption panel and its trailing bubble. `.clear`, the default, leaves them neutral
        /// glass; pass a colour only when it means something, with `captionInk` set to an ink that reads on it.
        /// Ignored for `.scrim`.
        public var captionFill: Color
        /// Text and glyph color in the caption panel. The default follows the appearance, dark in light mode and near
        /// white in dark, as text on neutral glass does. Ignored for `.scrim`, which is always white.
        public var captionInk: Color
        /// Resting shadow strength in light mode; dark mode uses about three times this.
        public var shadowOpacity: Double

        public init(
            caption: Caption = .block,
            captionFill: Color = .clear,
            captionInk: Color = Color(uiColor: UIColor { @Sendable traits in
                traits.userInterfaceStyle == .dark ? UIColor(red: 0.957, green: 0.953, blue: 0.937, alpha: 1) : UIColor(red: 0.078, green: 0.078, blue: 0.078, alpha: 1)
            }),
            shadowOpacity: Double = 0.12
        ) {
            self.caption = caption
            self.captionFill = captionFill
            self.captionInk = captionInk
            self.shadowOpacity = shadowOpacity
        }

        /// House default: a neutral glass panel with ink that follows the appearance.
        public static let standard = Style()
        /// White caption over a bottom scrim.
        public static let scrim = Style(caption: .scrim)
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.colorScheme) private var colorScheme

    private let image: Image
    private let eyebrow: String?
    private let title: String
    private let metadata: [String]
    private let trailingSymbol: String?
    private let height: CGFloat
    private let parallax: CGFloat
    private let cornerRadius: CGFloat
    private let style: Style
    private let action: (() -> Void)?

    public init(image: Image, eyebrow: String? = nil, title: String, metadata: [String] = [], trailingSymbol: String? = nil, height: CGFloat = 240, parallax: CGFloat = 0.25, cornerRadius: CGFloat = 26, style: Style = .standard, action: (() -> Void)? = nil) {
        self.image = image
        self.eyebrow = eyebrow
        self.title = title
        self.metadata = metadata
        self.trailingSymbol = trailingSymbol
        self.height = height
        self.parallax = parallax
        self.cornerRadius = cornerRadius
        self.style = style
        self.action = action
    }

    private var shadow: Double { min(style.shadowOpacity * (colorScheme == .dark ? 3 : 1), 1) }

    public var body: some View {
        if let action {
            Button(action: action) { card }
                .buttonStyle(Lift())
        } else {
            card
        }
    }

    /// Position of the card within the scroll viewport, -1 (entering at the bottom) to 1 (leaving at the top).
    nonisolated private static func progress(_ proxy: GeometryProxy) -> CGFloat {
        let frame = proxy.frame(in: .scrollView)
        let viewport = proxy.bounds(of: .scrollView)?.height ?? frame.height
        let raw = (frame.midY - viewport / 2) / max((viewport + frame.height) / 2, 1)
        return min(max(raw, -1), 1)
    }

    private var card: some View {
        let travel = reduceMotion ? 0 : height * parallax
        let tightens = !reduceMotion
        return Color.clear
            .frame(height: height)
            .overlay {
                image
                    .resizable()
                    .scaledToFill()
                    // Oversize the image by the maximum drift so the edges never show through.
                    .frame(height: height + travel * 2)
                    .visualEffect { content, proxy in
                        content.offset(y: -Self.progress(proxy) * travel)
                    }
                    .accessibilityHidden(true)
            }
            .overlay(alignment: .bottom) {
                if style.caption == .scrim {
                    // The scrim is tallest when the card is centered and tightens as it leaves the viewport. Squaring the
                    // progress eases it through the center instead of turning there on a sharp corner.
                    LinearGradient(colors: [.clear, .black.opacity(0.72)], startPoint: .top, endPoint: .bottom)
                        .frame(height: height * 0.6)
                        .visualEffect { content, proxy in
                            let progress = Self.progress(proxy)
                            return content.scaleEffect(y: tightens ? 1.3 - 0.4 * progress * progress : 1, anchor: .bottom)
                        }
                        .accessibilityHidden(true)
                }
            }
            .overlay(alignment: .bottomLeading) {
                Caption(eyebrow: eyebrow, title: title, metadata: metadata, trailingSymbol: trailingSymbol, cornerRadius: cornerRadius, style: style)
                    .visualEffect { content, proxy in
                        content.offset(y: -Self.progress(proxy) * travel / 3)
                    }
            }
            .clipShape(.rect(cornerRadius: cornerRadius, style: .continuous))
            .modifier(PressShade())
            // Cast by the card's outline alone: the glass caption draws in its own layer and would take the card's
            // shadow as a dark halo over the picture.
            .background { CardShadow(cornerRadius: cornerRadius, strength: shadow) }
            .fontWeight(.semibold)
            .accessibilityElement(children: .combine)
    }

    /// The caption slots, on a glass panel or as white text over the scrim, with the trailing glyph in a glass bubble
    /// joined to them. Reads the press state from the button style.
    private struct Caption: View {
        @Environment(\.accessibilityReduceMotion) private var reduceMotion
        @Environment(\.colorScheme) private var colorScheme
        @Environment(\.parallaxCardPressed) private var pressed
        let eyebrow: String?
        let title: String
        let metadata: [String]
        let trailingSymbol: String?
        let cornerRadius: CGFloat
        let style: Style

        var body: some View {
            let block = style.caption == .block
            let tint = block && style.captionFill != .clear ? style.captionFill : nil
            PieceLiquidGroup {
                // The panel and the bubble rest joined, so a liquid neck holds them together as one surface.
                HStack(alignment: .center, spacing: block ? PieceLiquid.joined : 12) {
                    if block {
                        slots(block: true)
                            .padding(16)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            // Concentric with the card: its corner less the inset.
                            .pieceLiquid(RoundedRectangle(cornerRadius: max(cornerRadius - 10, 12), style: .continuous), tint: tint, interactive: false)
                    } else {
                        // Over the scrim the text stays on the picture; only the bubble is glass.
                        slots(block: false)
                            .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    if let trailingSymbol {
                        bubble(trailingSymbol, tint: tint)
                    }
                }
            }
            .foregroundStyle(block ? style.captionInk : .white)
            .padding(block ? 10 : 20)
            // Over the scrim the bubble is dark glass, so the white arrow reads on the fallback material too.
            .environment(\.colorScheme, block ? colorScheme : .dark)
        }

        private func slots(block: Bool) -> some View {
            VStack(alignment: .leading, spacing: 3) {
                if let eyebrow {
                    Text(eyebrow.uppercased())
                        .font(.caption2.weight(.semibold))
                        .tracking(1)
                        .opacity(block ? 0.62 : 0.8)
                }
                Text(title)
                    .font(.system(.title2, weight: .semibold))
                    .tracking(-0.6)
                    .lineLimit(2)
                if !metadata.isEmpty {
                    HStack(spacing: 6) {
                        ForEach(Array(metadata.enumerated()), id: \.offset) { index, item in
                            if index > 0 {
                                Circle().frame(width: 3, height: 3).opacity(0.6)
                            }
                            Text(item)
                        }
                    }
                    .font(.subheadline.weight(.semibold))
                    .opacity(block ? 0.62 : 0.85)
                    .lineLimit(1)
                }
            }
        }

        /// The trailing glyph on a round glass bubble. Pressed, the bubble leans 2pt toward its arrow, so the neck to the
        /// panel thins as if the arrow were pulling it out.
        private func bubble(_ symbol: String, tint: Color?) -> some View {
            let motion = PieceMotion(reduceMotion: reduceMotion)
            let lean: CGFloat = pressed && !reduceMotion ? 2 : 0
            return Image(systemName: symbol)
                .font(.subheadline.weight(.semibold))
                .frame(width: 44, height: 44)
                .pieceLiquid(.circle, tint: tint, interactive: false)
                .offset(x: lean, y: -lean)
                // The bubble follows the card one rank behind on whichever spring the card is on: the tight press going
                // down, so it never bounces under the finger, and the elastic release coming back.
                .animation(pressed ? motion.follow(PieceMotion.tight, rank: 1) : motion.follow(rank: 1), value: pressed)
                .accessibilityHidden(true)
        }
    }

    /// Reduce Motion: a pressed card keeps its size and dims instead (brightens in dark mode, where the shadow barely
    /// shows). On the card, not its shadow, which stays dark. Reads the press from the button style.
    private struct PressShade: ViewModifier {
        @Environment(\.accessibilityReduceMotion) private var reduceMotion
        @Environment(\.colorScheme) private var colorScheme
        @Environment(\.parallaxCardPressed) private var pressed

        func body(content: Content) -> some View {
            content.brightness(pressed && reduceMotion ? (colorScheme == .dark ? 0.1 : -0.08) : 0)
        }
    }

    /// The card's shadow, from its outline. Pressed, it deepens and spreads; it reads the press from the button style.
    private struct CardShadow: View {
        let cornerRadius: CGFloat
        let strength: Double
        @Environment(\.parallaxCardPressed) private var pressed

        var body: some View {
            // A point inside the card's edge, so the fill casting the shadow never darkens the picture's antialiased rim.
            RoundedRectangle(cornerRadius: max(cornerRadius - 1, 0), style: .continuous)
                .fill(.black)
                .padding(1)
                .shadow(color: .black.opacity(pressed ? min(strength * 1.8, 1) : strength), radius: pressed ? 26 : 16, y: pressed ? 16 : 10)
        }
    }

    /// Press-to-lift: the card rises to 1.02 instead of sinking, its shadow deepens, and the trailing bubble leans toward
    /// its arrow a beat later, then everything springs back. It follows `isPressed`, so a scroll that takes over the
    /// touch settles the card the same way and nothing stays lifted.
    private struct Lift: ButtonStyle {
        @Environment(\.accessibilityReduceMotion) private var reduceMotion

        func makeBody(configuration: Configuration) -> some View {
            let motion = PieceMotion(reduceMotion: reduceMotion)
            let pressed = configuration.isPressed
            configuration.label
                // The shade and the shadow read this; under Reduce Motion the card keeps its size.
                .environment(\.parallaxCardPressed, pressed)
                .scaleEffect(pressed && !reduceMotion ? 1.02 : 1)
                .animation(pressed ? motion.press : motion.release, value: pressed)
        }
    }
}

private struct ParallaxCardPressedKey: EnvironmentKey {
    static let defaultValue = false
}

fileprivate extension EnvironmentValues {
    var parallaxCardPressed: Bool {
        get { self[ParallaxCardPressedKey.self] }
        set { self[ParallaxCardPressedKey.self] = newValue }
    }
}

