import SwiftUI

/// Liquid glass async action button whose whole lifecycle is one bound `phase`.
///
/// The capsule is glass, tinted for what it says: signal to act, sage once the work is done, butter on an error. While
/// the work runs a glass bubble buds out of the capsule's end carrying the progress ring, joined to it by a liquid
/// neck, and melts back in once the outcome has landed; on an error it stays out as the retry. The label morphs letter
/// by letter from one message to the next.
///
/// - Parameters:
///   - title: Idle label.
///   - phase: Bound `.idle`, `.loading`, `.success`, `.error(message)` or `.disabled`. The button returns itself to `.idle` after a success hold.
///   - tint: Overrides the style's glass tint while idle and loading, with white ink. `nil` uses `style.fill`.
///   - tintInk: The ink on `tint`, for a tint white doesn't read on (an app's accent and its ink). `nil` is white.
///   - errorTint: Overrides the style's error tint, with white ink. `nil` uses `style.errorFill`.
///   - successHold: How long the success state stays before the button returns to idle.
///   - successTitle: Text the label morphs to on success, such as "Saved", with a check beside it. `nil` keeps the check in its bubble until the hold ends.
///   - collapses: Draws the capsule in around its label while it works (the default), so the ring bubble buds out beside it. `false` keeps the capsule full width and makes room for the bubble at its end.
///   - style: Tints, ink, height and type. `.standard` is the house palette: signal, sage for success, butter for errors.
///   - action: Tap handler. Set `phase` to `.loading` inside it and to `.success` or `.error` when the work finishes.
public struct CommitButton: View {
    public enum Phase: Equatable {
        case idle, loading, success, error(String), disabled

        var isError: Bool { if case .error = self { return true } else { return false } }
    }

    /// Glass tints and metrics for every phase. Colors adapt to light and dark.
    public struct Style: Sendable {
        /// The capsule's glass tint while idle and loading: the primary action color. It also colors the spinning arc.
        public var fill: Color
        /// Ink on `fill`, `successFill` and `errorFill`.
        public var ink: Color
        /// The glass tint once the work succeeds, on the capsule and the ring bubble.
        public var successFill: Color
        /// The glass tint while showing an error, on the capsule and the retry bubble.
        public var errorFill: Color
        /// Unused since the liquid glass refactor: a disabled button is clear glass. Kept so existing code still compiles.
        public var disabledFill: Color
        /// Label color while `.disabled`.
        public var disabledInk: Color
        /// Height of the capsule; the ring bubble uses the same diameter. Never below 44.
        public var height: CGFloat
        /// Label font.
        public var font: Font

        public init(fill: Color = House.hex(0xFF0000), ink: Color = House.hex(0x141414), successFill: Color = House.hex(0xA9DCB7), errorFill: Color = House.hex(0xFFD976), disabledFill: Color = House.adaptive(light: 0xEAE8E2, dark: 0x262626), disabledInk: Color = House.adaptive(light: 0x8B8984, dark: 0x6F6D69), height: CGFloat = 56, font: Font = .body.weight(.semibold)) {
            self.fill = fill
            self.ink = ink
            self.successFill = successFill
            self.errorFill = errorFill
            self.disabledFill = disabledFill
            self.disabledInk = disabledInk
            self.height = Swift.max(height, 44)
            self.font = font
        }

        /// The Free house palette: signal, sage success, butter error, dark ink.
        public static let standard = Style()

        /// Builds house colors. Public so `Style` defaults can use it.
        public enum House {
            public static func hex(_ value: UInt32) -> Color {
                Color(red: Double((value >> 16) & 0xFF) / 255, green: Double((value >> 8) & 0xFF) / 255, blue: Double(value & 0xFF) / 255)
            }

            public static func adaptive(light: UInt32, dark: UInt32) -> Color {
                Color(uiColor: UIColor { @Sendable traits in
                    let v = traits.userInterfaceStyle == .dark ? dark : light
                    return UIColor(red: CGFloat((v >> 16) & 0xFF) / 255, green: CGFloat((v >> 8) & 0xFF) / 255, blue: CGFloat(v & 0xFF) / 255, alpha: 1)
                })
            }
        }
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Binding private var phase: Phase
    @State private var shownTitle: String
    @State private var ringClosed = false
    @State private var checkDrawn = false
    @State private var bloomed = false
    /// The arc turns on the clock while `spinning`. `restAngle` is where it rests, and where a spin starts from.
    @State private var spinning = false
    @State private var spinStart: Date = .now
    @State private var restAngle: Double = -90
    /// Outcomes that have landed. The pop and the shake key off these.
    @State private var pops = 0
    @State private var shakes = 0
    @State private var pressTicks = 0
    @State private var successTicks = 0
    @State private var errorTicks = 0
    /// The outcome on its way in, until its haptic plays.
    @State private var unfelt: Outcome?
    @State private var flow: Task<Void, Never>?
    /// The bubble at the capsule's end: out while the work runs, while the outcome lands and as the retry.
    @State private var buds = PieceBuds()

    private let title: String
    private let tint: Color?
    private let tintInk: Color?
    private let errorTint: Color?
    private let successHold: Duration
    private let successTitle: String?
    private let collapses: Bool
    private let style: Style
    private let action: () -> Void

    public init(_ title: String, phase: Binding<Phase>, tint: Color? = nil, tintInk: Color? = nil, errorTint: Color? = nil, successHold: Duration = .milliseconds(900), successTitle: String? = nil, collapses: Bool = true, style: Style = .standard, action: @escaping () -> Void) {
        self.title = title
        self._phase = phase
        self.tint = tint
        self.tintInk = tintInk
        self.errorTint = errorTint
        self.successHold = successHold
        self.successTitle = successTitle
        self.collapses = collapses
        self.style = style
        self.action = action
        self._shownTitle = State(initialValue: title)
    }

    /// Loading, and success until the label has bloomed into its success title (or for good when there is none):
    /// the ring shows in its bubble.
    private var working: Bool {
        phase == .loading || (phase == .success && !(bloomed && successTitle != nil))
    }

    /// The bubble is out while the ring shows and while an error offers the retry.
    private var bubbleWanted: Bool { working || phase.isError }

    /// Working, and set to draw the capsule in around its label.
    private var collapsed: Bool { collapses && working }

    /// The capsule's glass tint: signal to act, sage once done, butter on an error, clear while disabled.
    private var capsuleTint: Color? {
        switch phase {
        case .error: errorTint ?? style.errorFill
        case .success where ringClosed: style.successFill
        case .disabled: nil
        default: tint ?? style.fill
        }
    }

    private var ink: Color {
        switch phase {
        case .disabled: style.disabledInk
        case .error: errorTint == nil ? style.ink : .white
        case .success where ringClosed: style.ink
        default: tint == nil ? style.ink : (tintInk ?? .white)
        }
