    /// The bubble's tint while it is out: clear glass around the spinning ring, sage once it closes, butter as the retry.
    private var bubbleTint: Color? {
        switch phase {
        case .error: errorTint ?? style.errorFill
        case .success where ringClosed: style.successFill
        default: nil
        }
