    /// The success title has taken over the label, with the check beside it.
    private var showsCheck: Bool { phase == .success && bloomed && successTitle != nil }

    public var body: some View {
        Button {
            pressTicks += 1
            action()
        } label: {
            PieceLiquidGroup {
                HStack(spacing: 0) {
                    capsule
                        // Above the slot, so the bubble melting home slips under the capsule's end.
                        .zIndex(1)
                    slot
