        .buttonStyle(Press())
        .fontWeight(.semibold)
        .disabled(working || phase == .success || phase == .disabled)
        .pieceShake(trigger: shakes, distance: 10)
        .sensoryFeedback(.impact(flexibility: .soft), trigger: pressTicks)
        .sensoryFeedback(.success, trigger: successTicks)
        .sensoryFeedback(.error, trigger: errorTicks)
        .onAppear {
            if phase == .loading, !spinning { spin() }
            if case .error(let message) = phase { shownTitle = message }
            buds.place(bubbleWanted ? ["end"] : [])
        }
        .onChange(of: phase) { _, new in respond(to: new) }
        .onChange(of: bubbleWanted) { _, wanted in
            Task {
                if wanted {
                    await buds.bloom(["end"], reduceMotion: reduceMotion)
                } else {
                    await buds.gather(["end"], reduceMotion: reduceMotion)
