                .animation(motion.reveal, value: checkDrawn)
        }
        .frame(width: side, height: side)
    }

    /// The choreography, in beats. Glass first (the capsule draws in, the bubble buds, the tint turns), then content
    /// (the arc, the check, the label), then the outcome lands: its haptic with the pop or the shake, on one beat.
    private func respond(to phase: Phase) {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        flow?.cancel()
        // An outcome left before it lands is still felt, once. A retry or another outcome brings its own feedback.
        if let unfelt, phase == .idle || phase == .disabled { feel(unfelt) }
        unfelt = nil
        if phase == .loading { spin() } else { coast(motion) }
        switch phase {
        case .idle, .loading:
            // A ring still on screen (a retry set straight from success) reopens its arc rather than jumping.
            withAnimation(motion.dismiss) {
                ringClosed = false
                checkDrawn = false
            }
            bloomed = false
            shownTitle = title
        case .success:
            // The arc coasts on as it closes, and the capsule and the bubble turn sage with it.
            withAnimation(motion.morph) { ringClosed = true }
            unfelt = .success
            flow = Task {
                try? await Task.sleep(for: .milliseconds(reduceMotion ? 80 : 260))
                guard !Task.isCancelled else { return }
                checkDrawn = true
                land(.success)
                if let successTitle {
                    try? await Task.sleep(for: .milliseconds(reduceMotion ? 60 : 320))
                    guard !Task.isCancelled else { return }
                    // The bubble melts home with its check as the label morphs to the success title, the check now
                    // beside it, and the capsule opens back to full width.
                    withAnimation(motion.morph) {
                        bloomed = true
                        shownTitle = successTitle
                    }
                }
                try? await Task.sleep(for: successHold)
                guard !Task.isCancelled, self.phase == .success else { return }
                self.phase = .idle
            }
        case .error(let message):
            ringClosed = false
            checkDrawn = false
            bloomed = false
            shownTitle = message
            unfelt = .failure
            flow = Task {
                // Let the capsule open back out and the bubble turn into the retry, then the shake and its haptic land
                // together.
                try? await Task.sleep(for: .milliseconds(140))
                guard !Task.isCancelled else { return }
                land(.failure)
            }
        case .disabled:
            break
        }
    }

    private enum Outcome { case success, failure }

    /// The outcome lands: its haptic, and the pop or the shake.
    private func land(_ outcome: Outcome) {
        unfelt = nil
        feel(outcome)
        if outcome == .success { pops += 1 } else { shakes += 1 }
    }

    private func feel(_ outcome: Outcome) {
        if outcome == .success { successTicks += 1 } else { errorTicks += 1 }
    }

    /// Starts the arc turning from where it rests.
    private func spin() {
        spinStart = .now
        spinning = true
    }

    /// Lets a turning arc coast to rest at the speed it was turning, so it never stops dead.
    private func coast(_ motion: PieceMotion) {
        guard spinning else { return }
        guard motion.allowsAmbient else {
            withAnimation(motion.ambient) { spinning = false }
            return
        }
        let t = Date.now.timeIntervalSince(spinStart)
        let angle = restAngle + spun(t), speed = spinSpeed(t)
        let rest = PieceMotion.project(angle, velocity: speed)
        withAnimation(motion.settle(velocity: speed, from: angle, to: rest, spring: PieceMotion.calm)) {
            spinning = false
            restAngle = rest
        }
    }

    /// A spin reaches its one turn a second from rest over about three of these, so the arc winds up.
    private static let spinUp: Double = 0.15

    /// Degrees turned `t` seconds into a spin that starts from rest.
    private func spun(_ t: TimeInterval) -> Double {
        let t = max(t, 0)
        return 360 * (t - Self.spinUp * (1 - exp(-t / Self.spinUp)))
    }

    /// The spin's speed in degrees per second, `t` seconds in.
    private func spinSpeed(_ t: TimeInterval) -> Double {
        360 * (1 - exp(-max(t, 0) / Self.spinUp))
    }

    /// The still arc's opacity under Reduce Motion: a slow breath between full and 0.45 that starts at full.
    private func breath(_ t: TimeInterval) -> Double {
        0.725 + 0.275 * cos(2 * .pi * max(t, 0) / 1.2)
    }

    private var accessibilityValue: String {
        switch phase {
        case .idle: ""
        case .loading: "Loading"
        case .success: successTitle ?? "Done"
        case .error(let message): message
        case .disabled: "Disabled"
        }
    }

    /// Checkmark in unit space so it scales with the ring.
    private struct Checkmark: Shape {
        func path(in rect: CGRect) -> Path {
            var path = Path()
            path.move(to: CGPoint(x: rect.minX + rect.width * 0.08, y: rect.minY + rect.height * 0.55))
            path.addLine(to: CGPoint(x: rect.minX + rect.width * 0.38, y: rect.minY + rect.height * 0.85))
            path.addLine(to: CGPoint(x: rect.minX + rect.width * 0.92, y: rect.minY + rect.height * 0.2))
            return path
        }
    }

    /// The press darkens the capsule's glass a touch, in every mode. It reads the press from the button style, so
    /// only the capsule darkens, never the bubble beside it.
    private struct PressShade: View {
        @Environment(\.commitButtonPressed) private var pressed
        @Environment(\.accessibilityReduceMotion) private var reduceMotion

        var body: some View {
            let motion = PieceMotion(reduceMotion: reduceMotion)
            Capsule()
                .fill(.black.opacity(pressed ? 0.1 : 0))
                .animation(pressed ? motion.press : motion.release, value: pressed)
        }
    }

    /// The shared press, plus the capsule's darken. Loading and success are not dimmed like a normal disabled button.
    private struct Press: ButtonStyle {
        @Environment(\.accessibilityReduceMotion) private var reduceMotion

        func makeBody(configuration: Configuration) -> some View {
            // Under Reduce Motion the press darkens instead of sinking: the shared press would brighten this glass
            // in dark mode, the opposite of the darken.
            configuration.label
                .environment(\.commitButtonPressed, configuration.isPressed)
                .piecePress(configuration.isPressed && !reduceMotion)
        }
    }
}

