import SwiftUI

/// Success, failure or empty outcome view with one shared choreography: a ring, a solid block, an ink mark and one
/// liquid glass action.
///
/// The action is a signal-tinted glass capsule. While a retry runs, its label morphs to "Retrying" and it gives up a
/// little of its width to a progress bubble that buds out of its trailing end and rests joined to it by a liquid
/// neck; when the retry returns, the bubble melts back in and the capsule takes its width back.
///
/// - Parameters:
///   - outcome: `.success`, `.failure` or `.empty`. Sets the block, mark, and haptic.
///   - title: Headline, set large and tight.
///   - message: Supporting copy.
///   - primaryTitle: Primary button title when `retry` is not used.
///   - primaryAction: Primary button handler when `retry` is not used.
///   - retry: Optional async handler for failures; the primary button becomes "Try again", and until it returns the label reads "Retrying" with a progress bubble budded out of the button's end.
///   - secondary: Optional quiet second action.
///   - details: Optional technical text behind a "Details" disclosure on failures, on a glass panel.
///   - accent: Overrides the block color behind the mark. Defaults to the outcome's color in `style`.
///   - eyebrow: Optional small uppercase line above the title, such as "Synced 10:42".
///   - style: Block, signal and text colors. `.standard` is sage for success, butter for failure and sky for empty, with the brand red tinting the primary button's glass.
public struct OutcomeScreen: View {
    public enum Outcome: Sendable { case success, failure, empty }

    /// A secondary button.
    public struct Action {
        public let title: String
        public let handler: () -> Void

        public init(_ title: String, handler: @escaping () -> Void) {
            self.title = title
            self.handler = handler
        }
    }

    /// Colors for the outcome. Defaults follow the SwiftPieces house palette and adapt to light and dark.
    public struct Style: Sendable {
        /// Block behind the check.
        public var success: Color
        /// Block behind the cross.
        public var failure: Color
        /// Block behind the empty tray.
        public var empty: Color
        /// Mark color on the blocks.
        public var ink: Color
        /// The glass tint of the primary button: the one action color.
        public var signal: Color
        /// Primary button text.
        public var signalInk: Color
        /// Headline, drawing ring, progress bubble and details text color.
        public var text: Color
        /// Message, eyebrow and secondary action color.
        public var muted: Color
        /// The glass tint of the details block. `.clear`, the default, leaves it neutral glass.
        public var raised: Color

        public init(
            success: Color = Style.sage,
            failure: Color = Style.butter,
            empty: Color = Style.sky,
            ink: Color = Style.blockInk,
            signal: Color = Style.signalRed,
            signalInk: Color = Style.blockInk,
            text: Color = Style.adaptive(0x141414, 0xF4F3EF),
            muted: Color = Style.adaptive(0x5C5A56, 0xA6A49F),
            raised: Color = .clear
        ) {
            self.success = success
            self.failure = failure
            self.empty = empty
            self.ink = ink
            self.signal = signal
            self.signalInk = signalInk
            self.text = text
            self.muted = muted
            self.raised = raised
        }

        public static let standard = Style()

        public static let sage = Color(red: 0xA9 / 255, green: 0xDC / 255, blue: 0xB7 / 255)
        /// The brand red, `#FF0000`, kept under its earlier name so existing code still compiles.
        public static let tangerine = Color(red: 1, green: 0, blue: 0)
        public static let butter = Color(red: 1, green: 0xD9 / 255, blue: 0x76 / 255)
        public static let sky = Color(red: 0x9C / 255, green: 0xC2 / 255, blue: 1)
        /// The brand red, `#FF0000`: the one action color.
        public static let signalRed = Color(red: 1, green: 0, blue: 0)
        public static let blockInk = Color(red: 0x14 / 255, green: 0x14 / 255, blue: 0x14 / 255)

        /// A color that resolves to `light` or `dark` hex by the current appearance.
        public static func adaptive(_ light: UInt32, _ dark: UInt32) -> Color {
            Color(uiColor: UIColor { @Sendable traits in traits.userInterfaceStyle == .dark ? rgb(dark) : rgb(light) })
        }

        nonisolated private static func rgb(_ hex: UInt32) -> UIColor {
            UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
        }
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @ScaledMetric(relativeTo: .largeTitle) private var markSize: CGFloat = 112
    /// The outcome the block shows. It changes inside the choreography, so a new outcome recolors on its beat.
    @State private var shown: Outcome?
    @State private var ringTrim: CGFloat = 0
    /// True once color has pooled into the drawn ring, which then wears the block's color.
    @State private var pooled = false
    /// How far the block has pooled inward from the ring: 0 is the ring alone, 1 a solid disc.
    @State private var flood: CGFloat = 0
    /// Each mark draws on its own, so a new outcome lifts the old mark while the new one is pressed in.
    @State private var drawn: [Outcome: CGFloat] = [:]
    /// Bumped as each outcome lands. The haptic, the thud and the ripple key off it.
    @State private var landing = Landing()
    @State private var copyVisible = false
    @State private var actionsVisible = false
    @State private var isRetrying = false
    @State private var showsDetails = false
    /// The progress bubble: home inside the primary button's trailing end, out beside it while a retry runs.
    @State private var buds = PieceBuds()
    @ScaledMetric(relativeTo: .headline) private var buttonHeight: CGFloat = 56

    private let outcome: Outcome
    private let title: String
    private let message: String?
    private let primaryTitle: String
    private let primaryAction: () -> Void
    private let retry: (() async -> Void)?
    private let secondary: Action?
    private let details: String?
    private let accentOverride: Color?
    private let eyebrow: String?
    private let style: Style

    public init(
        outcome: Outcome,
        title: String,
        message: String? = nil,
        primaryTitle: String = "Continue",
        primaryAction: @escaping () -> Void = {},
        retry: (() async -> Void)? = nil,
        secondary: Action? = nil,
        details: String? = nil,
        accent: Color? = nil,
        eyebrow: String? = nil,
        style: Style = .standard
    ) {
        self.outcome = outcome
        self.title = title
        self.message = message
        self.primaryTitle = primaryTitle
        self.primaryAction = primaryAction
        self.retry = retry
        self.secondary = secondary
        self.details = details
        self.accentOverride = accent
        self.eyebrow = eyebrow
        self.style = style
    }

    private func block(for outcome: Outcome) -> Color {
        if let accentOverride { return accentOverride }
        switch outcome {
        case .success: return style.success
        case .failure: return style.failure
        case .empty: return style.empty
        }
    }

    private var usesRetry: Bool { outcome == .failure && retry != nil }

    public var body: some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        // Under Reduce Motion the copy and actions fade in where they sit instead of rising.
        let rise: CGFloat = reduceMotion ? 0 : 1
        VStack(spacing: 0) {
            mark
                .padding(.bottom, 28)
                .accessibilityHidden(true)

            VStack(spacing: 10) {
                if let eyebrow {
                    Text(eyebrow.uppercased())
                        .font(.caption.weight(.semibold))
                        .tracking(1)
                        .foregroundStyle(style.muted)
                }
                Text(title)
                    .font(.system(.largeTitle, weight: .semibold))
                    .tracking(-1.2)
                    .foregroundStyle(style.text)
                    .accessibilityAddTraits(.isHeader)
                if let message {
                    Text(message)
                        .font(.body)
                        .foregroundStyle(style.muted)
                }
            }
            .multilineTextAlignment(.center)
            .fixedSize(horizontal: false, vertical: true)
            .opacity(copyVisible ? 1 : 0)
            .offset(y: copyVisible ? 0 : 12 * rise)

            // Every glass shape of the actions in one group: the button and its progress bubble melt into each other.
            PieceLiquidGroup {
                VStack(spacing: 6) {
                    primaryRow

                    if let secondary {
                        Button(secondary.title, action: secondary.handler)
                            .font(.body.weight(.semibold))
                            .foregroundStyle(style.muted)
                            .frame(maxWidth: .infinity, minHeight: 48)
                            .contentShape(.rect)
                            .disabled(isRetrying)
                    }

                    if outcome == .failure, let details {
                        detailsBlock(details)
                            // A separate control: with the stack's 6pt it rests apart from the button, so the two
                            // never share a neck.
                            .padding(.top, secondary == nil ? PieceLiquid.apart - 6 : 2)
                    }
                }
            }
            .padding(.top, 32)
            .opacity(actionsVisible ? 1 : 0)
            .offset(y: actionsVisible ? 0 : 10 * rise)
        }
        .padding(28)
        .frame(maxWidth: .infinity)
        .fontWeight(.semibold)
        // A new outcome passed in place swaps the copy and actions and reflows them together, without a jump.
        .animation(motion.morph, value: outcome)
        .onChange(of: isRetrying) { _, retrying in
            Task {
                if retrying {
                    await buds.bloom(["progress"], reduceMotion: reduceMotion)
                } else {
                    await buds.gather(["progress"], reduceMotion: reduceMotion)
                }
            }
        }
        .sensoryFeedback(trigger: landing) { _, new in
            switch new.outcome {
            case .success: .success
            case .failure: .error
            case .empty: .impact(weight: .light)
            case nil: nil
            }
        }
        .task(id: outcome) { await play(outcome) }
    }

    /// The stamp: one ring that is drawn in ink and pools into the block, the ink marks, and the ripple behind them.
    private var mark: some View {
        let line = max(3, markSize * 0.03)
        let tone = block(for: shown ?? outcome)
        // Copied out of the environment for the ripple's animator, which re-runs its closure every frame.
        let ripples = !reduceMotion
        return ZStack {
            // One ripple as each outcome lands. Under Reduce Motion it never shows.
            Circle()
                .stroke(tone, lineWidth: 2)
                .keyframeAnimator(initialValue: CGFloat(1), trigger: landing.count) { ring, spread in
                    ring.scaleEffect(1 + 0.45 * spread).opacity(ripples ? 1 - spread : 0)
                } keyframes: { _ in
                    KeyframeTrack {
                        MoveKeyframe(0)
                        SpringKeyframe(1, duration: 0.7, spring: PieceMotion.calm)
                    }
                }
            ZStack {
                // Color pools inward from the ring as the ring takes the block's color, so the ring becomes the block.
                Flood(level: flood)
                    .fill(tone, style: FillStyle(eoFill: true))
                Circle()
                    .trim(from: 0, to: ringTrim)
                    .stroke(pooled ? tone : style.text, style: StrokeStyle(lineWidth: line, lineCap: .round))
                    .rotationEffect(.degrees(-90))
                    .padding(line / 2)
                ForEach(Self.kinds, id: \.self) { kind in
                    Glyph(outcome: kind, progress: drawn[kind] ?? 0, lineWidth: markSize * 0.075)
                        .fill(style.ink)
                        .padding(markSize * (kind == .failure ? 0.34 : 0.3))
                }
            }
            // The thud: the block is pressed in as the outcome lands, and the ripple spreads from under it.
            .piecePop(trigger: landing.count, amount: 0.06)
        }
        .frame(width: markSize, height: markSize)
        // Hidden until a run starts, so Reduce Motion can fade the whole stamp in.
        .opacity(shown == nil ? 0 : 1)
    }

    /// The primary action and, while a retry runs, its progress bubble. The button gives up the bubble's width plus a
    /// neck while the bubble is out, on the same spring, so the two rest joined; the bubble sits under the button, so at
    /// home it is inside the button's end.
    private var primaryRow: some View {
        let out = buds.isOut("progress")
        return ZStack(alignment: .trailing) {
            if buds.contains("progress") { progressBubble(out: out) }
            primaryButton
                .padding(.trailing, out ? buttonHeight + PieceLiquid.joined : 0)
        }
    }

    /// The one signal action on tinted glass. Its label morphs letter by letter: "Try again" to "Retrying" and back, or
    /// to the new title when a retry lands as a success.
    private var primaryButton: some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let label = isRetrying ? "Retrying" : (usesRetry ? "Try again" : primaryTitle)
        return Button {
            if usesRetry { Task { await performRetry() } } else { primaryAction() }
        } label: {
            PieceMorphText(text: label, font: .headline.weight(.semibold))
                .foregroundStyle(style.signalInk)
                .animation(motion.morph, value: label)
                .padding(.horizontal, 20)
                .frame(maxWidth: .infinity, minHeight: buttonHeight)
                .pieceLiquid(.capsule, tint: style.signal, interactive: false)
                .contentShape(.capsule)
        }
        // The liquid press, so the label sinks with its glass.
        .buttonStyle(PieceLiquidPressStyle())
        .disabled(isRetrying)
        .accessibilityLabel(label)
    }

    /// A round glass bubble with a spinner, out beside the button's trailing end while a retry runs. Home is just
    /// inside that end, shrunk, where the two are one shape. The button already says "Retrying", so it stays silent.
    private func progressBubble(out: Bool) -> some View {
        let home = buttonHeight / 2 + PieceLiquid.joined + buttonHeight * PieceLiquid.homeScale / 2
        return ProgressView()
            .tint(style.text)
            .pieceBudContent(out: out)
            .frame(width: buttonHeight, height: buttonHeight)
            .pieceLiquid(.circle, interactive: false)
            .pieceBud(out: out, home: CGSize(width: -home, height: 0))
            .accessibilityHidden(true)
    }

    private func detailsBlock(_ details: String) -> some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let panel = RoundedRectangle(cornerRadius: 20, style: .continuous)
        return VStack(alignment: .leading, spacing: 0) {
            Button {
                withAnimation(showsDetails ? motion.dismiss : motion.reveal) { showsDetails.toggle() }
            } label: {
                HStack {
                    Text("Details").font(.subheadline.weight(.semibold))
                    Spacer()
                    Image(systemName: "chevron.down")
                        .font(.caption.weight(.semibold))
                        .rotationEffect(.degrees(showsDetails ? 180 : 0))
                }
                .foregroundStyle(style.text)
                .frame(minHeight: 44)
                .contentShape(.rect)
            }
            .buttonStyle(.plain)
            .accessibilityValue(showsDetails ? "Expanded" : "Collapsed")

            if showsDetails {
                Text(details)
                    .font(.footnote.monospaced())
                    .foregroundStyle(style.muted)
                    .textSelection(.enabled)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.bottom, 14)
                    .transition(motion.transition(.opacity.combined(with: .move(edge: .top))))
            }
        }
        .padding(.horizontal, 16)
        // The text slides in under the header, so it is clipped to the panel before the glass is drawn around it.
        .clipShape(panel)
        .pieceLiquid(panel, tint: style.raised == .clear ? nil : style.raised, interactive: false)
    }

    /// The stamp, in beats. The ring is drawn in ink, color pools inward from it once it closes, the mark is pressed
    /// in, and the outcome lands: its haptic, the thud and one ripple together, then the copy rises and the actions
    /// a beat behind. A new outcome restamps in place: the old mark lifts as the block recolors, then the new mark
    /// lands. A run cut short by a newer outcome or by the view leaving stops where it is; the next carries on from there.
    private func play(_ outcome: Outcome) async {
        // Already landed and showing, as when the view reappears: nothing replays and nothing is felt twice.
        guard landing.outcome != outcome || shown != outcome else { return }
        let motion = PieceMotion(reduceMotion: reduceMotion)
        // Any other mark lifts first, quickly.
        withAnimation(motion.dismiss) {
            for kind in Self.kinds where kind != outcome { drawn[kind] = 0 }
        }
        if pooled {
            // Restamp: the block keeps its place and recolors, finishing a stamp that was cut short.
            withAnimation(motion.morph) {
                shown = outcome
                ringTrim = 1
                flood = 1
            }
        } else if reduceMotion {
            // Reduce Motion: the whole stamp fades in, then lands with its haptic. Nothing draws, pools or moves.
            var instant = Transaction()
            instant.disablesAnimations = true
            withTransaction(instant) {
                ringTrim = 1
                pooled = true
                flood = 1
                drawn[outcome] = 1
            }
            withAnimation(motion.reveal) { shown = outcome }
            guard await beat(0.2) else { return }
            land(outcome)
            return
        } else {
            shown = outcome
            withAnimation(motion.reveal) { ringTrim = 1 }
            // Color pools only once the ring has closed.
            guard await beat(0.42) else { return }
            withAnimation(motion.morph) {
                pooled = true
                flood = 1
            }
        }
        // A beat behind the block, the mark is pressed in; the outcome lands as it finishes.
        guard await beat(0.16) else { return }
        withAnimation(motion.morph) { drawn[outcome] = 1 }
        guard await beat(0.24) else { return }
        land(outcome)
    }

    /// The outcome lands: its haptic, the thud and the ripple on one beat, and the copy and actions arrive.
    private func land(_ outcome: Outcome) {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        landing = Landing(count: landing.count + 1, outcome: outcome)
        withAnimation(motion.reveal) { copyVisible = true }
        // The copy is read, so it rises on the calm reveal; the actions follow a beat behind with a follower's give.
        withAnimation(motion.cascade(motion.follow(rank: 1), index: 1, step: 0.12)) { actionsVisible = true }
    }

    /// Waits `seconds`; false when the run was cancelled meanwhile, so it stops instead of rushing the rest.
    private func beat(_ seconds: Double) async -> Bool {
        try? await Task.sleep(for: .seconds(seconds))
        return !Task.isCancelled
    }

    private func performRetry() async {
        guard let retry, !isRetrying else { return }
        isRetrying = true
        await retry()
        isRetrying = false
    }

    private static let kinds: [Outcome] = [.success, .failure, .empty]

    /// A landed outcome. Counted, so the same outcome landing twice is felt twice.
    private struct Landing: Equatable {
        var count = 0
        var outcome: Outcome?
    }

    /// The block, pooled inward from the ring: 0 is nothing, 1 a solid disc. Fill it even-odd.
    private struct Flood: Shape {
        var level: CGFloat

        var animatableData: CGFloat {
            get { level }
            set { level = newValue }
        }

        func path(in rect: CGRect) -> Path {
            var path = Path()
            guard level > 0 else { return path }
            path.addEllipse(in: rect)
            // The center closes by 90%, so the spring's long tail never leaves a speck under the mark as it draws.
            let depth = min(level / 0.9, 1) * min(rect.width, rect.height) / 2
            let hole = rect.insetBy(dx: depth, dy: depth)
            if !hole.isEmpty { path.addEllipse(in: hole) }
            return path
        }
    }

    /// Check, cross, or an open tray, each one path stroked to `progress` so it draws in order. The line thins to
    /// nothing over the first few percent, like a pen landing and lifting, so a lifted mark never leaves its round
    /// cap behind while the spring settles.
    private struct Glyph: Shape {
        var outcome: Outcome
        var progress: CGFloat
        var lineWidth: CGFloat

        var animatableData: CGFloat {
            get { progress }
            set { progress = newValue }
        }

        func path(in rect: CGRect) -> Path {
            let width = lineWidth * min(progress / 0.06, 1)
            guard width > 0 else { return Path() }
            return outline(in: rect)
                .trimmedPath(from: 0, to: progress)
                .strokedPath(StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round))
        }

        private func outline(in rect: CGRect) -> Path {
            var path = Path()
            let w = rect.width, h = rect.height, x = rect.minX, y = rect.minY
            switch outcome {
            case .failure:
                path.move(to: CGPoint(x: x, y: y))
                path.addLine(to: CGPoint(x: x + w, y: y + h))
                path.move(to: CGPoint(x: x + w, y: y))
                path.addLine(to: CGPoint(x: x, y: y + h))
            case .success:
                path.move(to: CGPoint(x: x, y: y + h * 0.54))
                path.addLine(to: CGPoint(x: x + w * 0.36, y: y + h * 0.88))
                path.addLine(to: CGPoint(x: x + w, y: y + h * 0.14))
            case .empty:
                path.move(to: CGPoint(x: x, y: y + h * 0.56))
                path.addLine(to: CGPoint(x: x + w * 0.3, y: y + h * 0.56))
                path.addLine(to: CGPoint(x: x + w * 0.38, y: y + h * 0.74))
                path.addLine(to: CGPoint(x: x + w * 0.62, y: y + h * 0.74))
                path.addLine(to: CGPoint(x: x + w * 0.7, y: y + h * 0.56))
                path.addLine(to: CGPoint(x: x + w, y: y + h * 0.56))
                path.addLine(to: CGPoint(x: x + w, y: y + h))
                path.addLine(to: CGPoint(x: x, y: y + h))
                path.closeSubpath()
                path.move(to: CGPoint(x: x + w * 0.18, y: y + h * 0.3))
                path.addLine(to: CGPoint(x: x + w * 0.82, y: y + h * 0.3))
                path.move(to: CGPoint(x: x + w * 0.3, y: y + h * 0.06))
                path.addLine(to: CGPoint(x: x + w * 0.7, y: y + h * 0.06))
            }
            return path
        }
    }
}

// MARK: - Example

/// A sync that fails, then lands as a success in place once "Try again" works. Tap the background to replay it.
private struct OutcomeScreenExample: View {
    @State private var synced = false
    @State private var run = 0

    var body: some View {
        OutcomeScreen(
            outcome: synced ? .success : .failure,
            title: synced ? "Backup complete" : "Couldn't sync",
            message: synced ? "2,418 photos and 36 videos are safe in your library." : "Check your connection and try again.",
            primaryTitle: "Done",
            retry: { [run] in await sync(run) },
            secondary: synced ? nil : .init("Not now") {},
            details: "URLSessionTask failed: The Internet connection appears to be offline. (NSURLErrorDomain -1009)",
            eyebrow: synced ? "Synced 10:42" : nil
        )
        .id(run)
        .padding(.horizontal, 12)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(OutcomeScreen.Style.adaptive(0xF3F2EE, 0x121212))
        .onTapGesture {
            synced = false
            run += 1
        }
    }

    /// Lands only for the run that started it: a replay mid-sync leaves the old retry running, and it must not
    /// turn the new run into a success.
    private func sync(_ attempt: Int) async {
        try? await Task.sleep(for: .seconds(1.2))
        if attempt == run { synced = true }
    }
}

