/// A capture bar with four modes. Voice becomes a live waveform and a running time, Photo a row of recent shots,
/// Timer a set of durations, Text the format controls. It opens and closes on its own so the morph can be watched.
private struct GlassModeBarExample: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var mode: String?
    @State private var minutes = 15

    private let modes: [GlassModeBarMode] = [
        .init(id: "text", systemImage: "textformat", title: "Text"),
        .init(id: "voice", systemImage: "mic", title: "Voice"),
        .init(id: "photo", systemImage: "photo", title: "Photo"),
        .init(id: "timer", systemImage: "timer", title: "Timer"),
    ]

    var body: some View {
        GlassModeBar(modes: modes, selection: $mode) { mode in
            AnyView(panel(mode.id))
        }
        .padding(.horizontal, 20)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(glassModeBarColor(light: 0xF3F2EE, dark: 0x121212))
        .task {
            while !Task.isCancelled {
                for next in ["voice", "timer", "photo", "text"] {
                    try? await Task.sleep(for: .seconds(0.9))
                    mode = next
                    try? await Task.sleep(for: .seconds(2.2))
                    mode = nil
                }
            }
        }
    }

    /// Each mode's controls span the whole inside of the capsule.
    @ViewBuilder private func panel(_ id: String) -> some View {
        let ink = glassModeBarColor(light: 0x141414, dark: 0xF4F3EF)
        let soft = ink.opacity(0.08)
        switch id {
        case "voice":
            HStack(spacing: 12) {
                TimelineView(.animation(paused: reduceMotion)) { context in
                    let t = context.date.timeIntervalSinceReferenceDate
                    // As many bars as fit, spread across the full width.
                    HStack(spacing: 0) {
                        ForEach(0..<28, id: \.self) { i in
                            Capsule()
                                .fill(Color(red: 1, green: 0, blue: 0))
                                .frame(width: 3, height: 6 + 18 * abs(sin(t * 3 + Double(i) * 0.6)))
                                .frame(maxWidth: .infinity)
                        }
                    }
                }
                .frame(height: 28)
                Text("0:07").monospacedDigit().foregroundStyle(ink)
            }
            .accessibilityElement(children: .ignore)
            .accessibilityLabel("Recording, 7 seconds")
        case "photo":
            HStack(spacing: 6) {
                ForEach([0x9CC2FF, 0xFFD976, 0xA9DCB7, 0xCDB8FF, 0xE9D5B3], id: \.self) { hex in
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .fill(glassModeBarColor(light: UInt32(hex), dark: UInt32(hex)))
                        .frame(maxWidth: .infinity)
                        .frame(height: 38)
                }
            }
            .accessibilityElement(children: .ignore)
            .accessibilityLabel("Recent photos")
        case "timer":
            HStack(spacing: 8) {
                ForEach([5, 15, 25, 45], id: \.self) { value in
                    Button { minutes = value } label: {
                        Text("\(value)m")
                            .foregroundStyle(ink)
                            .frame(maxWidth: .infinity)
                            .frame(height: 34)
                            .background(minutes == value ? ink.opacity(0.18) : soft, in: .capsule)
                    }
                    .buttonStyle(.plain)
                }
            }
        default:
            HStack(spacing: 0) {
                ForEach(["bold", "italic", "underline", "strikethrough", "list.bullet"], id: \.self) { symbol in
                    Image(systemName: symbol).frame(maxWidth: .infinity)
                }
            }
            .font(.body.weight(.semibold))
            .foregroundStyle(ink)
        }
    }
}

