import SwiftUI
import UIKit

/// A capture kind in a `GlassQuickAdd`: its row in the menu, and what the capture asks for.
public struct GlassQuickAddKind: Identifiable, Hashable, Sendable {
    public var id: String
    public var systemImage: String
    public var title: String
    /// The title field's placeholder in this kind's capture.
    public var prompt: String
    /// Option chips under the field (a due day, a flag, a time). Any number can be on.
    public var options: [String]
    /// The disc behind the kind's glyph.
    public var tint: Color

    public init(id: String, systemImage: String, title: String, prompt: String, options: [String] = [], tint: Color) {
        self.id = id
        self.systemImage = systemImage
        self.title = title
        self.prompt = prompt
        self.options = options
        self.tint = tint
    }
}

/// Where a `GlassQuickAdd` is: the pill, the menu of kinds, or one kind's capture.
public enum GlassQuickAddStage: Hashable, Sendable {
    case closed
    case menu
    case capture(String)
}

/// Colors of a `GlassQuickAdd`. `.standard` is the house palette.
public struct GlassQuickAddStyle: Sendable {
    /// Text and glyphs on the glass.
    public var label: Color
    /// Placeholders, the menu's heading and unselected chips' text.
    public var secondary: Color
    /// Glyphs and text on tinted shapes (the kind discs, Save).
    public var ink: Color
    /// Save's tint: signal, the brand red.
    public var action: Color
    /// Save's tint once saved: sage.
    public var success: Color

    /// Pass only what you want to change; `nil` keeps the house value.
    public init(label: Color? = nil, secondary: Color? = nil, ink: Color? = nil, action: Color? = nil, success: Color? = nil) {
        self.label = label ?? glassQuickAddColor(light: 0x141414, dark: 0xF4F3EF)
        self.secondary = secondary ?? glassQuickAddColor(light: 0x5C5A56, dark: 0xA6A49F)
        self.ink = ink ?? Color(red: 0x14 / 255, green: 0x14 / 255, blue: 0x14 / 255)
        self.action = action ?? Color(red: 1, green: 0, blue: 0)
        self.success = success ?? Color(red: 0.663, green: 0.863, blue: 0.718)
    }

    public static let standard = GlassQuickAddStyle()
}

/// A Quick add pill that folds up into a card: a menu of capture kinds, then the chosen kind's capture, all in the same
/// glass. Place it at the bottom of its space (a screen's bottom trailing corner, a toolbar) so it grows upward.
///
/// ```swift
/// GlassQuickAdd(kinds: [
///     .init(id: "task", systemImage: "checkmark.circle", title: "Task", prompt: "What needs doing?", options: ["Today", "Flag"], tint: .yellow),
///     .init(id: "note", systemImage: "note.text", title: "Note", prompt: "Write it down", tint: .blue),
/// ]) { kind, text, options in
///     store.add(kind.id, text, options)
/// }
/// ```
///
/// - Parameters:
///   - title: The pill's label. Defaults to "Quick add".
///   - kinds: What can be added, in menu order.
///   - stage: Optional two-way stage, to open the menu or a capture from your code. Without it the piece keeps its own.
///   - text: Optional two-way capture text, to keep a draft or fill it in.
///   - style: Colors. Defaults to the SwiftPieces house palette, adapting to light and dark.
///   - saveTrigger: Change it to save the open capture from your code, as if Save were tapped (a keyboard shortcut, a
///     toolbar button). Ignored while there is nothing to save.
///   - onSave: Runs with the kind, the trimmed text and the options that are on, when Save is tapped or Return pressed.
public struct GlassQuickAdd: View {
    public typealias Kind = GlassQuickAddKind
    public typealias Stage = GlassQuickAddStage
    public typealias Style = GlassQuickAddStyle

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @FocusState private var fieldFocused: Bool
    @State private var ownStage: Stage = .closed
    @State private var draft = ""
    @State private var picked: Set<String> = []
    /// The Save bubble: home inside the card's lower trailing corner until there is something to save.
    @State private var buds = PieceBuds()
    @State private var saveHeight: CGFloat = 48
    @State private var openTick = 0
    @State private var saveTick = 0
    /// Save's own beat after a tap: a spinner while it saves, then a check on sage, then it melts home.
    @State private var saveState: SaveState = .idle

    private enum SaveState { case idle, saving, saved }

    private let title: String
    private let kinds: [Kind]
    private let stageBinding: Binding<Stage>?
    private let textBinding: Binding<String>?
    private let style: Style
    private let saveTrigger: Int
    private let onSave: (Kind, String, Set<String>) -> Void

    public init(title: String = "Quick add", kinds: [Kind], stage: Binding<Stage>? = nil, text: Binding<String>? = nil, style: Style = .standard, saveTrigger: Int = 0, onSave: @escaping (Kind, String, Set<String>) -> Void) {
        self.saveTrigger = saveTrigger
        self.title = title
        self.kinds = kinds
        self.stageBinding = stage
        self.textBinding = text
        self.style = style
        self.onSave = onSave
    }

    private var stage: Stage { stageBinding?.wrappedValue ?? ownStage }
    private var field: Binding<String> { textBinding ?? $draft }
    private var capturing: Kind? {
        if case .capture(let id) = stage { return kinds.first { $0.id == id } }
        return nil
    }
    private var canSave: Bool { capturing != nil && !field.wrappedValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
    private var motion: PieceMotion { PieceMotion(reduceMotion: reduceMotion) }

    public var body: some View {
        let _ = (buds.present, buds.out)
        // One glass card and the Save bubble that buds from under its corner, joined.
        PieceLiquidGroup {
            VStack(alignment: .trailing, spacing: PieceLiquid.joined) {
                card
                if buds.contains("save") { saveButton }
            }
        }
        // Grows up and across from its lower trailing corner, wherever its container puts it.
        .frame(maxWidth: .infinity, alignment: .bottomTrailing)
        .fontWeight(.semibold)
        .animation(motion.morph, value: stage)
        .sensoryFeedback(.impact(flexibility: .soft, intensity: 0.6), trigger: openTick)
        .sensoryFeedback(.success, trigger: saveTick)
        .onChange(of: canSave) { _, ready in
            // Save buds out the moment there is something to save, and melts home if the field empties.
            Task {
                if ready {
                    if !buds.contains("save") { await buds.bloom(["save"], reduceMotion: reduceMotion) }
                } else if buds.contains("save") {
                    await buds.gather(["save"], reduceMotion: reduceMotion)
                }
            }
        }
        .onChange(of: saveTrigger) { save() }
        .onChange(of: stage) { _, new in
            if case .capture = new { fieldFocused = true } else { fieldFocused = false }
        }
    }

    // MARK: Card

    /// The one glass shape: a pill at rest, the menu or a capture once open. A 26pt continuous corner makes the 52pt
    /// pill a capsule and the card a rounded panel, so the shape never changes kind as it grows.
    private var card: some View {
        ZStack(alignment: .topLeading) {
            switch stage {
            case .closed:
                pill.transition(stageSwap)
            case .menu:
                menu.transition(stageSwap)
            case .capture:
                if let capturing { capture(capturing).transition(stageSwap) }
            }
        }
        .frame(maxWidth: stage == .closed ? nil : .infinity, alignment: .topLeading)
        .pieceLiquid(RoundedRectangle(cornerRadius: 26, style: .continuous), interactive: false)
    }

    /// Each stage's contents: the outgoing ones blur away quickly, the incoming ones sharpen in a beat later, once the
    /// glass is most of the way to its new size, so the two never smear together mid-resize.
    private var stageSwap: AnyTransition {
        .asymmetric(
            insertion: motion.swap.animation(motion.reveal.delay(reduceMotion ? 0 : 0.14)),
            removal: motion.swap.animation(motion.dismiss)
        )
    }

    private var pill: some View {
        Button { setStage(.menu) } label: {
            HStack(spacing: 8) {
                Image(systemName: "plus")
                Text(title)
            }
            .font(.body.weight(.semibold))
            .foregroundStyle(style.label)
            .padding(.horizontal, 20)
            .frame(minHeight: 52)
            .contentShape(.rect)
        }
        .buttonStyle(.plain)
    }

    private var menu: some View {
        VStack(alignment: .leading, spacing: 4) {
            header(Text(title).foregroundStyle(style.secondary))
            ForEach(kinds) { kind in
                Button {
                    picked = []
                    setStage(.capture(kind.id))
                } label: {
                    HStack(spacing: 12) {
                        disc(kind)
                        Text(kind.title)
                            .font(.body.weight(.semibold))
                            .foregroundStyle(style.label)
                        Spacer(minLength: 0)
                    }
                    .frame(minHeight: 48)
                    .contentShape(.rect)
                }
                .buttonStyle(.plain)
            }
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 12)
    }

    private func capture(_ kind: Kind) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            header(HStack(spacing: 10) {
                disc(kind, size: 28)
                Text(kind.title).foregroundStyle(style.label)
            })
            TextField("", text: field, prompt: Text(kind.prompt).foregroundStyle(style.secondary), axis: .vertical)
                .font(.title3.weight(.semibold))
                .foregroundStyle(style.label)
                .tint(style.label)
                .lineLimit(1...3)
                .focused($fieldFocused)
                .submitLabel(.done)
                .onSubmit(save)
            if !kind.options.isEmpty {
                // Chips are plain content inside the card's glass: a soft fill, stronger when on.
                HStack(spacing: 8) {
                    ForEach(kind.options, id: \.self) { option in
                        let on = picked.contains(option)
                        Button {
                            if on { picked.remove(option) } else { picked.insert(option) }
                        } label: {
                            Text(option)
                                .font(.subheadline.weight(.semibold))
                                .foregroundStyle(on ? style.label : style.secondary)
                                .padding(.horizontal, 14)
                                .frame(minHeight: 34)
                                .background(style.label.opacity(on ? 0.16 : 0.07), in: .capsule)
                        }
                        .buttonStyle(.plain)
                        .accessibilityAddTraits(on ? .isSelected : [])
                    }
                }
                .animation(motion.snap, value: picked)
            }
        }
        .padding(16)
    }

    /// A row with the given lead and a close button, at the top of the menu and of a capture.
    private func header(_ lead: some View) -> some View {
        HStack {
            lead.font(.subheadline.weight(.semibold))
            Spacer(minLength: 8)
            Button { setStage(.closed) } label: {
                Image(systemName: "xmark")
                    .font(.footnote.weight(.semibold))
                    .foregroundStyle(style.secondary)
                    .frame(width: 32, height: 32)
                    .background(style.label.opacity(0.07), in: .circle)
                    .frame(width: 44, height: 44)
                    .contentShape(.rect)
            }
            .buttonStyle(.plain)
            .accessibilityLabel("Close")
        }
    }

    private func disc(_ kind: Kind, size: CGFloat = 36) -> some View {
        Image(systemName: kind.systemImage)
            .font(.system(size: size * 0.42, weight: .semibold))
            .foregroundStyle(style.ink)
            .frame(width: size, height: size)
            .background(kind.tint, in: .circle)
            .accessibilityHidden(true)
    }

    // MARK: Save

    /// The signal bubble under the card's trailing corner, joined to it. It buds out of the card when there is text
    /// and melts back into the corner when there isn't, or once saved.
    private var saveButton: some View {
        let out = buds.isOut("save")
        let saved = saveState == .saved
        return Button(action: save) {
            HStack(spacing: 8) {
                // The beat: a spinner while it saves, a check once saved.
                ZStack {
                    switch saveState {
                    case .idle: EmptyView()
                    case .saving: ProgressView().controlSize(.small).tint(style.ink).transition(motion.swap)
                    case .saved: Image(systemName: "checkmark").transition(motion.swap)
                    }
                }
                PieceMorphText(text: saveState == .idle ? String(localized: "Save") : saved ? String(localized: "Saved") : String(localized: "Saving"), font: .body.weight(.semibold))
            }
                .font(.body.weight(.semibold))
                .foregroundStyle(style.ink)
                .pieceBudContent(out: out)
                .padding(.horizontal, 22)
                .frame(minHeight: 48)
                .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { saveHeight = $0 }
                .pieceLiquid(Capsule(), tint: out ? (saved ? style.success : style.action) : nil)
                .animation(motion.success, value: saveState)
        }
        .buttonStyle(PieceLiquidPressStyle())
        .disabled(!canSave)
        .pieceBud(out: out, home: CGSize(width: 0, height: -(saveHeight / 2 + PieceLiquid.joined + saveHeight * PieceLiquid.homeScale / 2)))
    }

    // MARK: Actions

    private func setStage(_ next: Stage) {
        if next == .menu, stage == .closed { openTick += 1 }
        if next == .closed { picked = [] }
        if let stageBinding { stageBinding.wrappedValue = next } else { ownStage = next }
    }

    private func save() {
        guard let kind = capturing, canSave, saveState == .idle else { return }
        let text = field.wrappedValue.trimmingCharacters(in: .whitespacesAndNewlines)
        let options = picked
        onSave(kind, text, options)
        fieldFocused = false
        withAnimation(motion.snap) { saveState = .saving }
        Task {
            // Saving, then saved with the success tap, then Save melts home and the card folds down into the pill.
            try? await Task.sleep(for: .milliseconds(reduceMotion ? 300 : 650))
            withAnimation(motion.success) { saveState = .saved }
            saveTick += 1
            AccessibilityNotification.Announcement(String(localized: "\(kind.title) added")).post()
            try? await Task.sleep(for: .milliseconds(reduceMotion ? 300 : 600))
            await buds.gather(["save"], reduceMotion: reduceMotion)
            saveState = .idle
            field.wrappedValue = ""
            setStage(.closed)
        }
    }
}

/// A house-palette colour that follows the interface style.
private func glassQuickAddColor(light: UInt32, dark: UInt32) -> Color {
    Color(uiColor: UIColor { @Sendable traits in
        let hex = traits.userInterfaceStyle == .dark ? dark : light
        return UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    })
}

