    @Environment(\.isEnabled) private var isEnabled
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @FocusState private var isFocused: Bool
    @ScaledMetric(relativeTo: .body) private var iconWidth: CGFloat = 32
