import SwiftUI

/// Liquid glass password field with strength meter, live requirements, and inline error.
///
/// The field is a glass shape with a round glass reveal bubble joined to it. Everything below it buds out of the
/// field when it appears and melts back into it when it goes: the error chip, joined just under it, and, apart from
/// it, the strength chip and the requirement chips.
///
/// - Parameters:
///   - label: Static caption above the field, also the placeholder and accessibility label.
///   - text: Bound password text.
///   - error: Validation message. Setting it from `nil` shakes the field once with an error haptic, tints it with `Style.error`, and buds an error chip out of its bottom edge. A new message for a standing error swaps in place; clear it to `nil` on edit so the next refused submit shakes again.
///   - showsStrength: Show the strength gauge and its label chip once text is non-empty.
///   - showsRequirements: Show the 8+ / number / symbol / mixed-case chips while focused or filled. When all four pass the field takes the success tint with a check, and the chips melt back into it a beat later.
///   - style: Colors and field metrics. Defaults to the SwiftPieces house palette, adapting to light and dark.
public struct SecureEntry: View {
    /// Colors and metrics. `.standard` is the house palette.
    public struct Style: Sendable {
        /// The glass tint of the field at rest. `.clear`, the default, leaves it neutral glass; an error or a complete password tints it with `error` or `success`.
        public var field: Color
        /// Typed text and the focus ring on neutral glass.
        public var label: Color
        /// Caption, placeholder and unmet requirements.
        public var secondaryLabel: Color
        /// The glass tint of the round reveal bubble. `.clear`, the default, leaves it neutral glass.
        public var button: Color
        /// Text and glyphs on tinted glass.
        public var ink: Color
        /// Strength tints from weak to strong, for the gauge and its chip. Four colors; shorter arrays repeat their last color.
        public var strength: [Color]
        /// The success tint: met requirement chips, and the field once every rule passes.
        public var success: Color
        /// The error tint: the field and its error chip.
        public var error: Color
        /// Field height, and the diameter of the reveal bubble.
        public var height: CGFloat
        /// Field corner radius.
        public var cornerRadius: CGFloat

        /// Pass only what you want to change; `nil` keeps the house palette value.
        public init(field: Color? = nil, label: Color? = nil, secondaryLabel: Color? = nil, button: Color? = nil, ink: Color? = nil, strength: [Color]? = nil, success: Color? = nil, error: Color? = nil, height: CGFloat = 56, cornerRadius: CGFloat = 18) {
            self.field = field ?? .clear
            self.label = label ?? adaptive(light: 0x141414, dark: 0xF4F3EF)
            self.secondaryLabel = secondaryLabel ?? adaptive(light: 0x5C5A56, dark: 0xA6A49F)
            self.button = button ?? .clear
            self.ink = ink ?? adaptive(light: 0x141414, dark: 0x141414)
            // Butter warns while the password is weak or fair; sage says it is good.
            self.strength = (strength?.isEmpty == false ? strength : nil) ?? [0xFFD976, 0xFFD976, 0xA9DCB7, 0xA9DCB7].map { adaptive(light: $0, dark: $0) }
            self.success = success ?? adaptive(light: 0xA9DCB7, dark: 0xA9DCB7)
            self.error = error ?? adaptive(light: 0xFFD976, dark: 0xFFD976)
            self.height = max(height, 44)
            self.cornerRadius = cornerRadius
        }

        public static let standard = Style()

        func strength(_ score: Int) -> Color { strength[min(max(score - 1, 0), strength.count - 1)] }
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.isEnabled) private var isEnabled
    @FocusState private var focus: Field?
    @State private var isRevealed = false
    @State private var shakeCount = 0
    /// Set a beat after the last rule is met, so the completed set tidies away after its last tile lands.
    @State private var collapsed: Bool
    @Binding private var text: String
    /// The parts below the field whose room is open. Each opens as its bubbles bud out of the field and closes as they
    /// melt home, on the same springs, so whatever sits below moves with them instead of jumping.
    @State private var open: Set<Part> = []
    @State private var buds = PieceBuds()
    /// The error the chip shows. It keeps the last message while the chip melts home after `error` clears.
    @State private var shownError: String?
    @State private var errorHeight: CGFloat = 0
    @State private var rulesHeight: CGFloat = 0

    private let label: String
    private let error: String?
    private let showsStrength: Bool
    private let showsRequirements: Bool
    private let style: Style

    private enum Field { case secure, plain }

    /// What sits below the field: the error chip, the strength gauge and the requirement chips.
    private enum Part: Hashable { case error, strength, rules }

    private struct Requirement: Identifiable {
        let id: String
        let met: Bool
    }

    private static let levels = ["Weak", "Fair", "Good", "Strong"]
    /// The strength chip's height.
    private let meterHeight: CGFloat = 22

    public init(_ label: String = "Password", text: Binding<String>, error: String? = nil, showsStrength: Bool = true, showsRequirements: Bool = true, style: Style = .standard) {
        self.label = label
        self._text = text
        self.error = error
        self.showsStrength = showsStrength
        self.showsRequirements = showsRequirements
        self.style = style
        // A field that opens already complete starts collapsed, so its set never tidies away on appear.
        self._collapsed = State(initialValue: showsRequirements && Self.requirements(for: text.wrappedValue).allSatisfy(\.met))
        self._shownError = State(initialValue: error)
    }

    private var complete: Bool { showsRequirements && Self.requirements(for: text).allSatisfy(\.met) }

    /// The parts that should show now. While typing, a set that just completed stays a beat so its last tile lands;
    /// leaving the field tidies it at once.
    private var wanted: Set<Part> {
        let isFocused = focus != nil
        var parts: Set<Part> = []
        if error != nil { parts.insert(.error) }
        if showsStrength && !text.isEmpty { parts.insert(.strength) }
        if complete ? isFocused && !collapsed : showsRequirements && (isFocused || !text.isEmpty) { parts.insert(.rules) }
        return parts
    }

    public var body: some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let requirements = Self.requirements(for: text)
        let passed = requirements.filter(\.met).count
        let complete = self.complete
        let completing = showsRequirements ? requirements.count : -1
        let isFocused = focus != nil
        let hasError = error != nil
        let checked = complete && !hasError
        let shape = RoundedRectangle(cornerRadius: style.cornerRadius, style: .continuous)
        // The field's glass carries its state: an error, a complete password, or its own resting tint.
        let fieldTint: Color? = hasError ? style.error : checked ? style.success : style.field == .clear ? nil : style.field
        let ink = fieldTint == nil ? style.label : style.ink
        // Every part below lines up with the field, so each buds straight down out of it.
        let column = style.height + PieceLiquid.joined
        // Read here, so this body observes the bubbles: the reads below sit in closures (the rooms' overlays, the grid) that are not re-run on
        // their own when a bubble changes, which would let one appear without its bud.
        let _ = (buds.present, buds.out)

        VStack(alignment: .leading, spacing: 10) {
            Text(label.uppercased())
                .font(.caption.weight(.semibold))
                .tracking(0.8)
                .foregroundStyle(style.secondaryLabel)

            PieceLiquidGroup {
                VStack(alignment: .leading, spacing: 0) {
                    // The field and the reveal bubble are one control, so they rest joined by a liquid neck.
                    HStack(spacing: PieceLiquid.joined) {
                        HStack(spacing: 8) {
                            Group {
                                if isRevealed {
                                    TextField(label, text: $text)
                                        .focused($focus, equals: .plain)
                                } else {
                                    SecureField(label, text: $text)
                                        .focused($focus, equals: .secure)
                                }
                            }
                            .font(.body.weight(.semibold))
                            .foregroundStyle(ink)
                            .tint(ink)
                            .textContentType(.password)
                            .textInputAutocapitalization(.never)
                            .autocorrectionDisabled()
                            .accessibilityLabel(label)

                            if checked {
                                Image(systemName: "checkmark")
                                    .font(.body.weight(.semibold))
                                    .foregroundStyle(style.ink)
                                    // The outcome blurs into the sage glass on the success haptic's beat.
                                    .transition(motion.swap)
                                    .accessibilityLabel("All requirements met")
                            }
                        }
                        .padding(.horizontal, 18)
                        .frame(height: style.height)
                        // The focus ring is the glass's own content: glass drawn over a separate ring would blur it.
                        // It sits a few points in from the edge, so the reveal bubble's neck never cuts through it.
                        .overlay {
                            RoundedRectangle(cornerRadius: max(style.cornerRadius - 3, 0), style: .continuous)
                                .strokeBorder(ink, lineWidth: 2)
                                .padding(3)
                                .opacity(isFocused ? 1 : 0)
                                .animation(motion.snap, value: isFocused)
                                .allowsHitTesting(false)
                        }
                        .pieceLiquid(shape, tint: fieldTint, interactive: false)

                        revealButton
                    }
                    // A new error shakes the field and its bubble once, on the beat of its haptic. Reduce Motion keeps it still.
                    .pieceShake(trigger: shakeCount)
                    // Over the rooms below it, so a bubble at home sits under the field and melts into it.
                    .zIndex(1)

                    Group {
                        slot(.error, gap: PieceLiquid.joined, height: errorHeight, measure: { errorHeight = $0 }) {
                            errorChip
                        }
                        slot(.strength, gap: PieceLiquid.apart, height: meterHeight, measure: { _ in }) {
                            meter(score: max(passed, 1))
                        }
                        slot(.rules, gap: PieceLiquid.apart, height: rulesHeight, measure: { rulesHeight = $0 }) {
                            rules(requirements, pops: !checked)
                        }
                    }
                    .padding(.trailing, column)
                }
            }
        }
        .fontWeight(.semibold)
        .opacity(isEnabled ? 1 : 0.45)
        // When several change in one update the first listed wins, so an error keeps its own role. The field's tint and
        // check are the outcome, on the success haptic's beat; the chips keep their own springs.
        .animation(hasError ? motion.error : motion.dismiss, value: error)
        .animation(checked ? motion.success : motion.dismiss, value: checked)
        .animation(motion.snap, value: passed)
        // One haptic per event: the rule that completes the set plays success, not a tick as well.
        .sensoryFeedback(.selection, trigger: passed) { old, new in new > old && new != completing }
        .sensoryFeedback(.success, trigger: complete) { old, new in !old && new }
        .sensoryFeedback(.error, trigger: shakeCount)
        .onAppear { sync(wanted, animated: false) }
        .onChange(of: wanted) { _, parts in sync(parts) }
        .onChange(of: error) { old, new in
            // An error arriving is the refusal. A parent rewording one already shown doesn't shake or buzz again.
            if old == nil, new != nil { shakeCount += 1 }
            if let new { shownError = new }
        }
        .onChange(of: complete) { _, now in
            if !now { collapsed = false }
        }

        // Cancelled when a rule is lost again or the field goes away, so the set never collapses over unmet rules.
        .task(id: complete) {
            guard complete else { return }
            try? await Task.sleep(for: .milliseconds(400))
            guard !Task.isCancelled else { return }
            withAnimation(motion.dismiss) { collapsed = true }
        }
    }

    /// The round glass bubble joined to the field's end. Its glyph blurs from one eye to the other.
    private var revealButton: some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        return Button(action: toggleReveal) {
            ZStack {
                Image(systemName: isRevealed ? "eye.slash" : "eye")
                    .font(.body.weight(.semibold))
                    .foregroundStyle(style.button == .clear ? style.label : style.ink)
                    .id(isRevealed)
                    .transition(motion.swap)
            }
            .animation(motion.snap, value: isRevealed)
            .frame(width: style.height, height: style.height)
            .pieceLiquid(.circle, tint: style.button == .clear ? nil : style.button, interactive: false)
            .contentShape(.circle)
        }
        .buttonStyle(PieceLiquidPressStyle())
        .accessibilityLabel(isRevealed ? "Hide password" : "Show password")
    }

    /// Room in the column for a part. It opens to its content's height plus `gap` and closes to nothing, on the
    /// springs its bubbles bud and melt on. The content is always laid out, so its height is known before it opens.
    private func slot(_ part: Part, gap: CGFloat, height: CGFloat, measure: @escaping (CGFloat) -> Void, @ViewBuilder content: () -> some View) -> some View {
        Color.clear
            .frame(height: open.contains(part) ? gap + height : 0)
            .frame(maxWidth: .infinity)
            .overlay(alignment: .topLeading) {
                content()
                    .fixedSize(horizontal: false, vertical: true)
                    .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { measure($0) }
                    .padding(.top, gap)
            }
    }

    /// How far above a bubble's place its home is: just inside the field's bottom edge, straight up through whatever
    /// rooms are open above it. `depth` is the distance from the top of its own room to its centre.
    private func homeOffset(above parts: [Part], depth: CGFloat, height: CGFloat) -> CGSize {
        let rooms = parts.reduce(CGFloat(0)) { total, part in
            guard open.contains(part) else { return total }
            switch part {
            case .error: return total + PieceLiquid.joined + errorHeight
            case .strength: return total + PieceLiquid.apart + meterHeight
            case .rules: return total + PieceLiquid.apart + rulesHeight
            }
        }
        return CGSize(width: 0, height: -(rooms + depth + height * PieceLiquid.homeScale / 2))
    }

    /// The error chip: butter glass joined just under the field. Its message blurs from one wording to the next, and
    /// it keeps the last one while it melts home.
    @ViewBuilder private var errorChip: some View {
        let message = error ?? shownError ?? ""
        let face = HStack(spacing: 6) {
            Image(systemName: "exclamationmark")
                .font(.caption2.weight(.semibold))
            Text(message)
                .font(.footnote.weight(.semibold))
                .id(message)
                .transition(PieceMotion(reduceMotion: reduceMotion).swap)
        }
        .foregroundStyle(style.ink)
        .padding(.horizontal, 12)
        .padding(.vertical, 7)
        ZStack(alignment: .topLeading) {
            face.hidden()
            if buds.contains("error") {
                let out = buds.isOut("error")
                face
                    .pieceBudContent(out: out)
                    .pieceLiquid(.capsule, tint: out ? style.error : nil, interactive: false)
                    .pieceBud(out: out, home: homeOffset(above: [], depth: PieceLiquid.joined + errorHeight / 2, height: errorHeight))
                    .accessibilityElement(children: .ignore)
                    .accessibilityLabel("Error: \(message)")
            }
        }
    }

    /// A gauge whose fill and tint move with the score, and a glass chip in the same tint whose label morphs from one
    /// level to the next. The chip buds out of the field as typing starts; the gauge fades in beside it.
    private func meter(score: Int) -> some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let color = style.strength(score)
        let out = buds.isOut("strength")
        return HStack(spacing: 10) {
            GeometryReader { proxy in
                ZStack(alignment: .leading) {
                    Capsule().fill(style.secondaryLabel.opacity(0.18))
                    Capsule().fill(color).frame(width: proxy.size.width * CGFloat(score) / 4)
                }
            }
            .frame(height: 8)
            // The gauge is a reading, not chrome: it fades in with the chip and out ahead of it.
            .opacity(out ? 1 : 0)
            .animation(out ? motion.reveal : motion.dismiss, value: out)
            ZStack {
                Color.clear.frame(width: 64, height: meterHeight)
                if buds.contains("strength") {
                    PieceMorphText(text: Self.levels[score - 1].uppercased(), font: .caption2.weight(.semibold))
                        .tracking(0.8)
                        .foregroundStyle(style.ink)
                        .pieceBudContent(out: out)
                        .frame(width: 64, height: meterHeight)
                        .pieceLiquid(.capsule, tint: out ? color : nil, interactive: false)
                        .pieceBud(out: out, home: homeOffset(above: [.error], depth: PieceLiquid.apart + meterHeight / 2, height: meterHeight))
                }
            }
        }
        // A gauge, not a toy: the fill changes length without overshoot, so the reading never wobbles.
        .animation(motion.value, value: score)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("Password strength")
        .accessibilityValue(Self.levels[score - 1])
        // Laid out even while its room is closed, so VoiceOver reads it only while the chip is there.
        .accessibilityHidden(!buds.contains("strength"))
    }

    /// The requirement chips, two to a row, resting apart. Each cell is always laid out, so the grid's height is known
    /// before its chips bud.
    private func rules(_ requirements: [Requirement], pops: Bool) -> some View {
        Grid(horizontalSpacing: PieceLiquid.apart, verticalSpacing: PieceLiquid.apart) {
            ForEach([0, 2], id: \.self) { start in
                GridRow {
                    ForEach(start..<min(start + 2, requirements.count), id: \.self) { i in
                        rule(requirements[i], index: i, pops: pops)
                    }
                }
            }
        }
    }

    /// Unmet: neutral glass with an empty ring. Met: sage glass whose check draws in after the tint lands.
    /// `pops` is off for the rule that completes the set: the field's tint and check are that outcome, so they land alone.
    private func rule(_ requirement: Requirement, index: Int, pops: Bool) -> some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let id = "rule\(index)"
        let out = buds.isOut(id)
        let row = CGFloat(index / 2)
        let chipHeight = max((rulesHeight - PieceLiquid.apart) / 2, 0)
        let face = HStack(spacing: 6) {
            ZStack {
                Circle().strokeBorder(style.secondaryLabel.opacity(0.6), lineWidth: 1.5)
                    .opacity(requirement.met ? 0 : 1)
                Checkmark()
                    .trim(from: 0, to: requirement.met ? 1 : 0)
                    .stroke(style.ink, style: StrokeStyle(lineWidth: 2, lineCap: .round, lineJoin: .round))
                    .padding(2)
                    // The check draws once the tint has landed; a lost rule clears it at once.
                    .animation(requirement.met ? motion.snap.delay(0.08) : motion.dismiss, value: requirement.met)
            }
            .frame(width: 14, height: 14)
            Text(requirement.id)
                .font(.footnote.weight(.semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.8)
        }
        .foregroundStyle(requirement.met ? style.ink : style.secondaryLabel)
        .padding(.horizontal, 12)
        .frame(maxWidth: .infinity, minHeight: 32, alignment: .leading)
        return ZStack {
            face.hidden()
            if buds.contains(id) {
                face
                    .pieceBudContent(out: out)
                    // A met rule clicks into its tint on its tick's beat; a lost one drains back. The tint drains at
                    // home too, so a sage chip never sits over the field as it melts in.
                    .pieceLiquid(.capsule, tint: out && requirement.met ? style.success : nil, interactive: false)
                    .pieceLiquidScale(requirement.met && !reduceMotion ? 1 : 0.98)
                    .animation(requirement.met ? motion.snap : motion.dismiss, value: requirement.met)
                    // A met rule clicks into its tint with a small dip and swell on its tick's beat, the glass and its
                    // label together. The trigger is the rule's state, which changes once per edit. Reduce Motion
                    // keeps the tint change without the pop.
                    .pieceLiquidPop(trigger: requirement.met, amount: requirement.met && pops ? 0.04 : 0)
                    .pieceBud(out: out, home: homeOffset(above: [.error, .strength], depth: PieceLiquid.apart + row * (chipHeight + PieceLiquid.apart) + chipHeight / 2, height: chipHeight))
                    .accessibilityElement(children: .ignore)
                    .accessibilityLabel(requirement.id)
                    .accessibilityValue(requirement.met ? "Met" : "Not met")
            }
        }
    }

    /// Opens or closes each part's room to match `parts`, budding its bubbles out of the field or melting them home.
    /// `animated: false` puts them straight in place, for the first frame.
    private func sync(_ parts: Set<Part>, animated: Bool = true) {
        let ids: (Part) -> [String] = { part in
            switch part {
            case .error: ["error"]
            case .strength: ["strength"]
            case .rules: (0..<4).map { "rule\($0)" }
            }
        }
        guard animated else {
            var quiet = Transaction()
            quiet.disablesAnimations = true
            withTransaction(quiet) { open = parts }
            buds.place([Part.error, .strength, .rules].filter(parts.contains).flatMap(ids))
            return
        }
        for part in [Part.error, .strength, .rules] where parts.contains(part) != open.contains(part) {
            if parts.contains(part) {
                withAnimation(PieceLiquid.split(reduceMotion: reduceMotion)) { _ = open.insert(part) }
                Task { await buds.bloom(ids(part), reduceMotion: reduceMotion) }
            } else {
                withAnimation(PieceLiquid.home(reduceMotion: reduceMotion)) { _ = open.remove(part) }
                Task { await buds.gather(ids(part), reduceMotion: reduceMotion) }
            }
        }
    }

    private func toggleReveal() {
        let wasFocused = focus != nil
        isRevealed.toggle()
        // Hand focus to the replacement field so the keyboard stays up.
        if wasFocused { focus = isRevealed ? .plain : .secure }
    }

    private static func requirements(for password: String) -> [Requirement] {
        [
            Requirement(id: "8+ characters", met: password.count >= 8),
            Requirement(id: "A number", met: password.contains(where: \.isNumber)),
            Requirement(id: "A symbol", met: password.contains { !$0.isLetter && !$0.isNumber && !$0.isWhitespace }),
            Requirement(id: "Mixed case", met: password.contains(where: \.isUppercase) && password.contains(where: \.isLowercase))
        ]
    }

    /// Checkmark drawn in unit space so it scales with its frame.
    private struct Checkmark: Shape {
        nonisolated func path(in rect: CGRect) -> Path {
            var path = Path()
            path.move(to: CGPoint(x: rect.minX + rect.width * 0.1, y: rect.minY + rect.height * 0.55))
            path.addLine(to: CGPoint(x: rect.minX + rect.width * 0.4, y: rect.minY + rect.height * 0.85))
            path.addLine(to: CGPoint(x: rect.minX + rect.width * 0.9, y: rect.minY + rect.height * 0.2))
            return path
        }
    }
}

/// A house-palette color that follows the interface style.
private func adaptive(light: UInt32, dark: UInt32) -> Color {
    Color(uiColor: UIColor { @Sendable traits in
        let hex = traits.userInterfaceStyle == .dark ? dark : light
        return UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    })
}

