    var reduceMotion: Bool

    func body(content: Content, phase: TransitionPhase) -> some View {
        let still = phase.isIdentity || reduceMotion
        return content
            .pieceLiquidScale(still ? 1 : scale)
            .offset(x: still ? 0 : shift)
            .opacity(phase.isIdentity ? 1 : 0)
    }
}

