import SwiftUI

/// Wrapping liquid glass token entry bound to an array of strings: tags, skills, recipients.
///
/// The input is a glass capsule and every token a glass chip beside it, resting apart. A committed token buds out of
/// the input where it was typed; a removed one melts back into it. Suggestions bud out of the input as a glass list.
///
/// - Parameters:
///   - placeholder: Shown in the input while it is empty, and the input's accessibility label.
///   - tokens: Bound tokens, in order. Changes from outside bud in and melt out like typed ones.
///   - suggestions: Candidates listed under the field while typing, matched case- and diacritic-insensitively (prefix matches first, then contains), excluding tokens already added.
///   - maxTokens: Upper limit. When reached the input stops accepting text and shows a quiet count such as "5/5", which bumps when a keystroke is refused; backspace still removes.
///   - allowsDuplicates: When `false`, an entry that matches an existing token case-insensitively is not added; the existing chip is highlighted instead and the first spelling is kept.
///   - separators: Keys and characters that commit the typed text. `.standard` is return, comma and pasted line breaks. Full-width commas and semicolons count as their ASCII forms.
///   - style: Colors and field metrics. Defaults to the SwiftPieces house palette, adapting to light and dark.
///   - validate: Accepts or rejects a trimmed entry (for example an email check). A rejected entry stays in the input, the field shakes, the input takes the error tint and an error haptic plays.
public struct TokenField: View {
    /// What commits the typed text into a token.
    public struct Separators: OptionSet, Sendable {
        public let rawValue: Int
        public init(rawValue: Int) { self.rawValue = rawValue }

        /// The return key (and a hardware Return).
        public static let `return` = Separators(rawValue: 1 << 0)
        /// `,` and the full-width `，` and `、`.
        public static let comma = Separators(rawValue: 1 << 1)
        /// Line breaks inside pasted or dictated text.
        public static let newline = Separators(rawValue: 1 << 2)
        /// `;` and the full-width `；`. Common in pasted recipient lists.
        public static let semicolon = Separators(rawValue: 1 << 3)
        /// A space. Useful for emails and single-word tags; leave it off for multi-word tags.
        public static let space = Separators(rawValue: 1 << 4)

        /// Return, comma and pasted line breaks.
        public static let standard: Separators = [.return, .comma, .newline]
    }

    /// Colors and metrics. `.standard` is the house palette.
    public struct Style: Sendable {
        /// The glass tint of the input and the suggestion list. `.clear`, the default, leaves them neutral glass.
        public var field: Color
        /// Glass tints for chips. A token keeps the same tint wherever it appears (picked from its text). `[.clear]`, the default, leaves every chip neutral glass.
        public var chips: [Color]
        /// Text and the remove glyph on tinted glass.
        public var ink: Color
        /// Typed text, suggestions, chip text on neutral glass and the focus ring.
        public var label: Color
        /// Placeholder, the limit count and the unmatched part of a suggestion.
        public var placeholder: Color
        /// The input's tint after a rejected entry.
        public var error: Color
        /// The tint of a highlighted chip, armed for removal.
        public var selection: Color
        /// Corner radius of the suggestion list. The chips and the input are capsules.
        public var cornerRadius: CGFloat
        /// Minimum height of the field. Its chips and input are centred in it.
        public var minHeight: CGFloat

        /// Pass only what you want to change; `nil` keeps the house palette value.
        public init(field: Color? = nil, chips: [Color]? = nil, ink: Color? = nil, label: Color? = nil, placeholder: Color? = nil, error: Color? = nil, selection: Color? = nil, cornerRadius: CGFloat = 18, minHeight: CGFloat = 56) {
            self.field = field ?? .clear
            self.chips = (chips?.isEmpty == false ? chips : nil) ?? [.clear]
            self.ink = ink ?? adaptive(light: 0x141414, dark: 0x141414)
            self.label = label ?? adaptive(light: 0x141414, dark: 0xF4F3EF)
            self.placeholder = placeholder ?? adaptive(light: 0x5C5A56, dark: 0xA6A49F)
            self.error = error ?? adaptive(light: 0xFFD976, dark: 0xFFD976)
            self.selection = selection ?? adaptive(light: 0xFF0000, dark: 0xFF0000)
            self.cornerRadius = cornerRadius
            self.minHeight = max(minHeight, 44)
        }

        public static let standard = Style()

        /// A stable color per token text (case-insensitive), so chips never swap colors as others are removed.
        func chip(for text: String) -> Color {
            var hash: UInt64 = 5381
            for scalar in text.lowercased().unicodeScalars { hash = (hash &* 33) &+ UInt64(scalar.value) }
            return chips[Int(hash % UInt64(chips.count))]
        }

        /// A chip's glass tint: none for `.clear`, so the house chips stay neutral glass.
        func tint(for text: String) -> Color? {
            let color = chip(for: text)
            return color == .clear ? nil : color
        }
    }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.isEnabled) private var isEnabled
    @FocusState private var isFocused: Bool
    @ScaledMetric(relativeTo: .subheadline) private var chipHeight: CGFloat = 40
    @ScaledMetric(relativeTo: .body) private var minInputWidth: CGFloat = 88
    @Binding private var tokens: [String]
    /// Raw input text. Always starts with `sentinel`; see `fieldChanged`.
    @State private var fieldText = TokenField.sentinel
    /// The last value written to `fieldText` by `setDraft`, so the change it causes is not treated as an edit.
    @State private var programmatic: String?
    @State private var selectedID: String?
    @State private var isInvalid = false
    @State private var shakeCount = 0
    @State private var addTick = 0
    @State private var armTick = 0
    @State private var removeTick = 0
    @State private var rejectTick = 0
    @State private var limitBump = 0
    /// A duplicate's swell on the highlighted chip, from 0 to 1 and back.
    @State private var swellBeat: CGFloat = 0
    /// Dims the ring for a beat, for a refusal with nothing else to show on screen.
    @State private var ringBeat = 0
    /// The width chips flow in. A wrap travels most of it, so a wide field reflows without overshoot.
    @State private var flowWidth: CGFloat = 0
    /// Chips out at their place, and the suggestion list: a chip is home inside the input until it buds out.
    @State private var buds = PieceBuds()
    /// Where each chip was born: the middle of the text it was typed as, and the input it was typed into. Its home
    /// until it is out.
    @State private var births: [String: Birth] = [:]
    /// Where the next commit is born, set just before it writes the tokens.
    @State private var birth: Birth?
    /// Chips removed from the flow, melting back into the input from where they were.
    @State private var melts: [Melt] = []
    @State private var meltCount = 0
    /// Frames in the field's space: each chip's, the input's, and the whole field's.
    @State private var frames: [String: CGRect] = [:]
    @State private var inputFrame: CGRect = .zero
    @State private var flowFrame: CGRect = .zero
    /// The typed text's width, so a commit is born under it.
    @State private var draftWidth: CGFloat = 0
    /// The list's last rows, kept while it melts home after the matches clear.
    @State private var shownMatches: [String] = []
    @State private var listHeight: CGFloat = 0

    private let placeholder: String
    private let suggestions: [String]
    private let maxTokens: Int?
    private let allowsDuplicates: Bool
    private let separators: Separators
    private let style: Style
    private let validate: (String) -> Bool
    /// Chips are separate entries, so they rest outside the merge distance and only goo while one buds or melts.
    private let spacing = PieceLiquid.apart

    /// A zero-width space kept in front of the typed text. iOS gives no callback for backspace on an empty
    /// software-keyboard field (`onKeyPress(.delete)` only sees hardware keys), but with this character in
    /// place the "empty" field still has one character to delete, so the text becoming `""` is a reliable
    /// backspace signal for both keyboards. It is never shown, stored or committed.
    private static let sentinel = "\u{200B}"

    private struct Item: Identifiable {
        let id: String
        let text: String
    }

    /// Where a chip is born: under the text it was typed as, inside the input as it was then.
    private struct Birth {
        let point: CGPoint
        let input: CGRect

        /// The centre of a chip `width` wide at home: under the text, but shrunk inside the input's ends.
        func home(width: CGFloat) -> CGPoint {
            let half = width * PieceLiquid.homeScale / 2 + 2
            let x = input.width > half * 2 ? min(max(point.x, input.minX + half), input.maxX - half) : input.midX
            return CGPoint(x: x, y: point.y)
        }
    }

    /// A removed chip, drawn over the flow where it was until it has melted into the input.
    private struct Melt: Identifiable {
        let id: String
        let token: String
        let text: String
        let frame: CGRect
        let tint: Color?
    }

    public init(_ placeholder: String, tokens: Binding<[String]>, suggestions: [String] = [], maxTokens: Int? = nil, allowsDuplicates: Bool = false, separators: Separators = .standard, style: Style = .standard, validate: @escaping (String) -> Bool = { _ in true }) {
        self.placeholder = placeholder
        self._tokens = tokens
        self.suggestions = suggestions
        self.maxTokens = maxTokens.map { max($0, 0) }
        self.allowsDuplicates = allowsDuplicates
        self.separators = separators
        self.style = style
        self.validate = validate
    }

    private var motion: PieceMotion { PieceMotion(reduceMotion: reduceMotion) }
    private var draft: String { Self.strip(fieldText) }
    private var isFull: Bool { maxTokens.map { tokens.count >= $0 } ?? false }
    private var fieldTint: Color? { style.field == .clear ? nil : style.field }

    public var body: some View {
        let motion = self.motion
        let matches = self.matches
        // Read here, so this body observes the bubbles: the reads below sit in closures (the flow's ForEach, the list, the melts) that are not re-run on
        // their own when a bubble changes, which would let one appear without its bud.
        let _ = (buds.present, buds.out)
        PieceLiquidGroup {
            VStack(alignment: .leading, spacing: 0) {
                // Over the list, so the list at home sits under the input and melts into it.
                field.zIndex(1)
                suggestionList(matches)
                    // Rows refine in place as you type, on `value`, which never overshoots: they are text being read,
                    // and typing stays calm. Scoped to the list, so the field, caret and typed text never ride along
                    // when a keystroke changes the matches.
                    .animation(motion.value, value: matches)
            }
            // Behind the flow, so a removed chip slips under the chips it crosses and ends under the input.
            .background(alignment: .topLeading) { meltLayer }
            .coordinateSpace(.named("tokenField"))
        }
        .fontWeight(.semibold)
        .opacity(isEnabled ? 1 : 0.45)
        .sensoryFeedback(.selection, trigger: addTick)
        .sensoryFeedback(.impact(flexibility: .soft, intensity: 0.6), trigger: armTick)
        .sensoryFeedback(.impact(flexibility: .rigid, intensity: 0.8), trigger: removeTick)
        .sensoryFeedback(.error, trigger: rejectTick)
        .sensoryFeedback(.impact(weight: .light, intensity: 0.7), trigger: limitBump)
        .onAppear { buds.place(Self.ids(for: tokens)) }
        .onChange(of: fieldText) { old, new in fieldChanged(from: old, to: new) }
        .onChange(of: isFocused) { _, focused in
            guard !focused else { return }
            selectedID = nil
            commitOnBlur()
        }
        .onChange(of: tokens) { old, new in tokensChanged(from: old, to: new) }
        .onChange(of: matches) { old, new in
            if !new.isEmpty { shownMatches = new }
            guard old.isEmpty != new.isEmpty else { return }
            Task {
                if new.isEmpty {
                    await buds.gather(["list"], reduceMotion: reduceMotion)
                } else {
                    await buds.bloom(["list"], reduceMotion: reduceMotion)
                }
            }
        }
    }

    // MARK: Field

    private var field: some View {
        let motion = self.motion
        return FlowLayout(spacing: spacing, lineSpacing: spacing) {
            ForEach(items) { item in
                chip(item)
                    // A chip buds in and melts out on its own, so the flow only moves the rest.
                    .transition(.identity)
            }
            input
                .layoutValue(key: FlowFill.self, value: minInputWidth)
        }
        // A reflow overshoots by a share of how far it travels. On a phone that stays inside the gaps; on a wider field
        // (landscape, iPad) a wrap crosses most of the line, so it lands without overshoot instead.
        .animation(flowWidth > 400 ? motion.value : motion.snap, value: tokens)
        .onGeometryChange(for: CGFloat.self) { $0.size.width } action: { flowWidth = $0 }
        .frame(maxWidth: .infinity, minHeight: style.minHeight, alignment: .leading)
        .onGeometryChange(for: CGRect.self) { $0.frame(in: .named("tokenField")) } action: { flowFrame = $0 }
        .contentShape(.rect)
        // Tapping anywhere that is not a chip puts the caret in the input.
        .onTapGesture { if isEnabled { isFocused = true } }
        // Chips reflow inside the field's own space, so when a change from outside resizes the field and its parent
        // moves it (a centered stack), they move with the field instead of sliding across its edge.
        .geometryGroup()
        // An entry refused back into the input shakes the field once, on the beat of the error haptic.
        .pieceShake(trigger: shakeCount)
        .accessibilityElement(children: .contain)
    }

    private var items: [Item] {
        zip(Self.ids(for: tokens), tokens).map { Item(id: $0, text: $1) }
    }

    /// Identity by text, with an occurrence suffix when duplicates are allowed, so removing one chip
    /// animates that chip rather than the last one.
    private static func ids(for tokens: [String]) -> [String] {
        var seen: [String: Int] = [:]
        return tokens.map { token in
            let n = seen[token, default: 0]
            seen[token] = n + 1
            return n == 0 ? token : "\(token)\u{0}\(n)"
        }
    }

    /// A token's text and remove glyph, padded to its capsule.
    private func chipFace(_ text: String) -> some View {
        HStack(spacing: 0) {
            Text(text)
                .font(.subheadline.weight(.semibold))
                .lineLimit(1)
                .truncationMode(.middle)
            Image(systemName: "xmark")
                .font(.caption2.weight(.semibold))
                .frame(width: 28)
        }
        .padding(.leading, 14)
        .padding(.trailing, 4)
        .frame(minHeight: chipHeight)
    }

    /// A glass chip. Born home inside the input, under the text it was typed as, it buds out to its place in the flow;
    /// highlighted, it takes the selection tint and lifts.
    private func chip(_ item: Item) -> some View {
        let isSelected = selectedID == item.id
        let still = reduceMotion
        let gap = spacing
        let out = buds.isOut(item.id)
        let frame = frames[item.id]
        let home = frame.flatMap { frame in births[item.id].map { birth in
            let point = birth.home(width: frame.width)
            return CGSize(width: point.x - frame.midX, height: point.y - frame.midY)
        } } ?? .zero
        let tint = isSelected ? style.selection : style.tint(for: item.text)
        // A duplicate swells its chip every time, so one that is already highlighted, where the lift has nothing left
        // to do, still answers. The swell takes only the room the lift leaves before the spacing, up to 4%, so a long
        // recipient never slides under its neighbor or past the field's edge. Reduce Motion, and a chip too long to
        // swell, dim its label for a beat instead.
        let width = max(frame?.width ?? 1, 1)
        let room = min(max(gap - width * 0.02, 0) * 2 / (width * 1.04), 0.04)
        let swells = !still && room > 0.004
        return HStack(spacing: 0) {
            Text(item.text)
                .font(.subheadline.weight(.semibold))
                .lineLimit(1)
                .truncationMode(.middle)
            Button { remove(id: item.id) } label: {
                Image(systemName: "xmark")
                    .font(.caption2.weight(.semibold))
                    .frame(width: 28, height: chipHeight)
                    // The glyph is small; the hit area grows to at least 44pt around it.
                    .contentShape(.rect.inset(by: -8))
            }
            .buttonStyle(InkPressStyle())
            .disabled(!isEnabled)
        }
        .foregroundStyle(tint == nil ? style.label : style.ink)
        .opacity(isSelected && !swells ? 1 - Double(swellBeat) * 0.5 : 1)
        .pieceBudContent(out: out)
        .padding(.leading, 14)
        .padding(.trailing, 4)
        .frame(minHeight: chipHeight)
        // A tinted chip passes its tint only while out, so it drains as it melts into the input.
        .pieceLiquid(.capsule, tint: out ? tint : nil, interactive: false)
        .pieceLiquidScale(isSelected && swells ? 1 + swellBeat * room : 1)
        // A highlighted chip lifts slightly. It answers a tap or a key, so it snaps rather than settling elastically.
        .pieceLiquidScale(isSelected && !reduceMotion ? 1.04 : 1)
        .animation(motion.snap, value: isSelected)
        // A chip just added waits one layout pass, closed to nothing (glass ignores opacity), for its place to be
        // measured, so it starts from its home.
        .pieceLiquidScale(frame == nil && !out ? 0.001 : 1)
        .pieceBud(out: out, home: home)
        .onGeometryChange(for: CGRect.self) { $0.frame(in: .named("tokenField")) } action: { frames[item.id] = $0 }
        .contentShape(.rect)
        .onTapGesture {
            guard isEnabled else { return }
            selectedID = isSelected ? nil : item.id
            isFocused = true
        }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("\(item.text), token")
        .accessibilityAddTraits(isSelected ? .isSelected : [])
        .accessibilityAction(named: "Remove") { remove(id: item.id) }
    }

    /// Removed chips, where they were in the flow, melting into the input's leading end.
    private var meltLayer: some View {
        ZStack(alignment: .topLeading) {
            ForEach(melts) { melt in
                let out = buds.isOut(melt.id)
                let home = CGPoint(x: inputFrame.minX + min(melt.frame.width * PieceLiquid.homeScale / 2 + 4, inputFrame.width / 2), y: inputFrame.midY)
                chipFace(melt.text)
                    .foregroundStyle(melt.tint == nil ? style.label : style.ink)
                    .pieceBudContent(out: out)
                    .pieceLiquid(.capsule, tint: out ? melt.tint : nil, interactive: false)
                    .fixedSize()
                    .pieceBud(out: out, home: CGSize(width: home.x - melt.frame.midX, height: home.y - melt.frame.midY))
                    .position(x: melt.frame.midX, y: melt.frame.midY)
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    /// The input is a glass capsule that takes the rest of the chips' last line. It sizes from a hidden copy of its
    /// text, so the flow layout can ask for its natural width and wrap it to a new line when the rest of the current
    /// line is too narrow.
    private var input: some View {
        let showsCount = isFull && draft.isEmpty
        let hint = showsCount ? "\(tokens.count)/\(maxTokens ?? 0)" : placeholder
        let still = reduceMotion
        let motion = self.motion
        let tint = isInvalid ? style.error : fieldTint
        let ink = tint == nil ? style.label : style.ink
        // A capsule while it holds one line, rounding off as wrapped text grows it.
        let shape = RoundedRectangle(cornerRadius: chipHeight / 2, style: .continuous)
        return Text(draft.isEmpty ? hint : draft)
            .font(.body.weight(.semibold))
            .lineLimit(draft.isEmpty ? 1 : 4)
            .onGeometryChange(for: CGFloat.self) { $0.size.width } action: { draftWidth = $0 }
            .padding(.trailing, 6)
            .hidden()
            .frame(maxWidth: .infinity, minHeight: chipHeight, alignment: .leading)
            .overlay(alignment: .leading) {
                ZStack(alignment: .leading) {
                    // Hidden rather than removed while typing: a refused keystroke renders once with its character
                    // before the field puts the text back, and a removed hint would lose the bump it triggers.
                    Text(hint)
                        .font(showsCount ? .body.weight(.semibold).monospacedDigit() : .body.weight(.semibold))
                        .foregroundStyle(tint == nil ? style.placeholder : style.ink.opacity(0.6))
                        .lineLimit(1)
                        // A keystroke refused at the limit pushes the count against its bound and it rebounds. Reduce
                        // Motion dims it for a beat instead.
                        .keyframeAnimator(initialValue: CGFloat(1), trigger: limitBump) { content, scale in
                            content
                                .scaleEffect(still ? 1 : scale, anchor: .leading)
                                .opacity(still ? 1 - Double(max(scale - 1, 0)) * 3 : 1)
                        } keyframes: { _ in
                            SpringKeyframe(1.12, duration: 0.1, spring: PieceMotion.tight)
                            SpringKeyframe(1, duration: 0.3, spring: PieceMotion.elastic)
                        }
                        .opacity(draft.isEmpty ? 1 : 0)
                        .allowsHitTesting(false)
                        .accessibilityHidden(true)
                    // Vertical axis: return inserts a line break we can see and handle in `fieldChanged`,
                    // instead of `onSubmit`, which ends editing and drops the keyboard between tokens.
                    TextField("", text: $fieldText, axis: .vertical)
                        .font(.body.weight(.semibold))
                        .lineLimit(1...4)
                        .foregroundStyle(ink)
                        .tint(ink)
                        .focused($isFocused)
                        .onSubmit(commitTyped)
                        .accessibilityLabel(inputLabel)
                }
            }
            .padding(.horizontal, 16)
            // The ring is the glass's own content: glass drawn over a separate ring would blur it. It sits a few
            // points in from the edge, so chips budding from the field meet clean glass and their necks never cut it.
            .overlay {
                RoundedRectangle(cornerRadius: max(chipHeight / 2 - 3, 0), style: .continuous)
                    .strokeBorder(ink, lineWidth: 2)
                    .padding(3)
                    .opacity(isFocused || isInvalid ? 1 : 0)
                    // A refusal with nothing else on screen dims the ring for a beat, even when it was already showing:
                    // a refused entry under Reduce Motion, which has no shake, or a keystroke at the limit while the
                    // input holds text, which hides the count.
                    .keyframeAnimator(initialValue: 1.0, trigger: ringBeat) { ring, level in
                        ring.opacity(level)
                    } keyframes: { _ in
                        SpringKeyframe(0.2, duration: 0.1, spring: PieceMotion.tight)
                        SpringKeyframe(1, spring: PieceMotion.calm)
                    }
                    .animation(isInvalid ? motion.error : motion.dismiss, value: isInvalid)
                    .animation(motion.snap, value: isFocused)
                    .allowsHitTesting(false)
            }
            // Scoped to the glass, so the keystroke that clears an error never animates the typed text. The first
            // listed wins when both change in one update, so an error keeps its own role.
            .animation(isInvalid ? motion.error : motion.dismiss) { glass in
                glass.pieceLiquid(shape, tint: tint, interactive: false)
            }
            .onGeometryChange(for: CGRect.self) { $0.frame(in: .named("tokenField")) } action: { inputFrame = $0 }
    }

    private var inputLabel: String {
        let count = tokens.count
        if let maxTokens { return "\(placeholder), \(count) of \(maxTokens) tokens" }
        return "\(placeholder), \(count) \(count == 1 ? "token" : "tokens")"
    }

    /// Where a commit made now is born: the middle of the typed text, inside the input.
    private var typedCenter: CGPoint {
        CGPoint(x: inputFrame.minX + 16 + min(draftWidth, max(inputFrame.width - 32, 0)) / 2, y: inputFrame.midY)
    }

    // MARK: Suggestions

    private var matches: [String] {
        let query = draft.trimmingCharacters(in: .whitespaces)
        guard isFocused, !query.isEmpty, !isFull, !suggestions.isEmpty else { return [] }
        var seen = Set(tokens.map(Self.fold))
        var prefix: [String] = [], contains: [String] = []
        for candidate in suggestions {
            guard seen.insert(Self.fold(candidate)).inserted,
                  let range = candidate.range(of: query, options: [.caseInsensitive, .diacriticInsensitive], locale: .current)
            else { continue }
            if range.lowerBound == candidate.startIndex { prefix.append(candidate) } else { contains.append(candidate) }
        }
        return Array((prefix + contains).prefix(5))
    }

    /// A glass list that buds out of the input, shrunk inside it, and rests apart below the field, opening room for
    /// itself as it comes and closing it as it melts home, so whatever sits below moves with it.
    @ViewBuilder private func suggestionList(_ matches: [String]) -> some View {
        if buds.contains("list") {
            let out = buds.isOut("list")
            let rows = matches.isEmpty ? shownMatches : matches
            let query = draft.trimmingCharacters(in: .whitespaces)
            // Home: the list's centre on the input's, shrunk until it fits inside it.
            let width = max(flowFrame.width, 1)
            let center = CGPoint(x: width / 2, y: flowFrame.maxY + listHeight / 2)
            let fit = min(1, inputFrame.width * 0.8 / (width * PieceLiquid.homeScale), inputFrame.height * 0.8 / max(listHeight * PieceLiquid.homeScale, 1))
            VStack(alignment: .leading, spacing: 0) {
                ForEach(rows, id: \.self) { candidate in
                    Button { commitSuggestion(candidate) } label: {
                        HStack(spacing: 12) {
                            if let tint = style.tint(for: candidate) {
                                Circle().fill(tint).frame(width: 10, height: 10)
                            } else {
                                Image(systemName: "plus")
                                    .font(.caption.weight(.semibold))
                                    .foregroundStyle(style.placeholder)
                                    .frame(width: 10)
                            }
                            Text(highlight(query, in: candidate))
                                .font(.body.weight(.semibold))
                                .multilineTextAlignment(.leading)
                        }
                        .padding(.horizontal, 16)
                        .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
                        .contentShape(.rect)
                    }
                    // A full-width row sinks only slightly, so its mark and text barely shift.
                    .buttonStyle(InkPressStyle(depth: 1.5))
                    .accessibilityLabel(candidate)
                    .accessibilityHint("Adds as a token")
                }
            }
            .pieceBudContent(out: out)
            .padding(.vertical, 4)
            .frame(maxWidth: .infinity)
            .pieceLiquid(RoundedRectangle(cornerRadius: style.cornerRadius, style: .continuous), tint: out ? fieldTint : nil, interactive: false)
            .fixedSize(horizontal: false, vertical: true)
            .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { listHeight = $0 }
            .pieceLiquidScale(out || reduceMotion ? 1 : fit)
            // Closed to nothing until its height is known (glass ignores opacity), so its first home is inside the input.
            .pieceLiquidScale(listHeight == 0 ? 0.001 : 1)
            .pieceBud(out: out, home: CGSize(width: inputFrame.midX - center.x, height: inputFrame.midY - center.y))
            .padding(.top, out ? spacing : 0)
            .frame(height: out ? nil : 0, alignment: .top)
        }
    }

    /// The matched run in full ink, the rest of the candidate quieter.
    private func highlight(_ query: String, in candidate: String) -> AttributedString {
        guard let range = candidate.range(of: query, options: [.caseInsensitive, .diacriticInsensitive], locale: .current) else {
            var whole = AttributedString(candidate)
            whole.foregroundColor = style.label
            return whole
        }
        var before = AttributedString(String(candidate[..<range.lowerBound]))
        var match = AttributedString(String(candidate[range]))
        var after = AttributedString(String(candidate[range.upperBound...]))
        before.foregroundColor = style.placeholder
        match.foregroundColor = style.label
        after.foregroundColor = style.placeholder
        return before + match + after
    }

    // MARK: Editing

    private static func strip(_ text: String) -> String { text.replacingOccurrences(of: sentinel, with: "") }
    private static func fold(_ text: String) -> String { text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current) }

    private func isSeparator(_ c: Character) -> Bool {
        if c.isNewline { return true } // Only present here when a newline separator applies; see fieldChanged.
        if separators.contains(.comma), c == "," || c == "，" || c == "、" { return true }
        if separators.contains(.semicolon), c == ";" || c == "；" { return true }
        if separators.contains(.space), c == " " || c == "\u{3000}" { return true }
        return false
    }

    private func setDraft(_ text: String) {
        let value = Self.sentinel + text
        guard fieldText != value else { return }
        programmatic = value
        fieldText = value
    }

    /// Every edit lands here. Our own writes through `setDraft` re-enter once and are skipped.
    private func fieldChanged(from old: String, to new: String) {
        if new == programmatic {
            programmatic = nil
            return
        }
        // The sentinel itself was deleted: backspace on an empty input.
        if new.isEmpty {
            setDraft("")
            backspaceOnEmpty()
            return
        }
        let oldBody = Self.strip(old)
        var body = Self.strip(new)
        guard body != oldBody else {
            setDraft(body) // Keeps the sentinel in front if the caret was moved before it.
            return
        }
        selectedID = nil
        let inserted = body.count - oldBody.count

        // At the limit typing meets a bound, not an error: a light tap and the count bumps, with no shake or error
        // haptic on every keystroke. The count only shows in an empty input, so with text still in it (entries kept
        // past the limit) the ring dims instead. The text is put back unchanged, so an error tint already showing stays.
        if isFull, inserted > 0 {
            limitBump += 1
            if !oldBody.isEmpty { ringBeat += 1 }
            setDraft(oldBody)
            return
        }
        isInvalid = false

        // A single inserted line break is the return key; more text arriving at once is a paste or dictation.
        let isPaste = inserted > 1
        if body.contains(where: \.isNewline) {
            let splits = isPaste ? separators.contains(.newline) : separators.contains(.return)
            if !splits { body = String(body.compactMap { $0.isNewline ? (isPaste ? " " : nil) : $0 }) }
        }

        // Commit only when a separator was just added, so leftovers kept in the input are not re-checked on every keystroke.
        let separatorCount = body.filter(isSeparator).count
        if separatorCount > oldBody.filter(isSeparator).count {
            var parts = body.split(omittingEmptySubsequences: false, whereSeparator: isSeparator).map(String.init)
            // Typing a separator commits what precedes it; a paste commits every part.
            let tail = isPaste ? "" : (parts.popLast() ?? "")
            let leftovers = commit(parts)
            let joiner = separators.contains(.comma) ? ", " : separators.contains(.semicolon) ? "; " : " "
            setDraft((leftovers + [tail]).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }.joined(separator: joiner))
            return
        }

        // No leading blanks in an otherwise empty input.
        setDraft(body.allSatisfy(\.isWhitespace) ? "" : body)
    }

    private func commitTyped() {
        if separators.contains(.return) { setDraft(commit([draft]).joined(separator: " ")) }
        isFocused = true
    }

    private func commitSuggestion(_ candidate: String) {
        let leftovers = commit([candidate])
        if leftovers.isEmpty { setDraft("") }
        isFocused = true
    }

    /// Leaving the field keeps valid typed text as a token, quietly.
    private func commitOnBlur() {
        guard !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        setDraft(commit([draft], feedback: false).joined(separator: " "))
    }

    /// Adds every acceptable part in one animated change. Returns the parts that were rejected (invalid or over the limit).
    @discardableResult
    private func commit(_ parts: [String], feedback: Bool = true) -> [String] {
        var next = tokens
        var added: [String] = []
        var leftovers: [String] = []
        var duplicate: Int?
        for part in parts {
            let token = part.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !token.isEmpty else { continue }
            if let maxTokens, next.count >= maxTokens { leftovers.append(token); continue }
            if !allowsDuplicates, let index = next.firstIndex(where: { $0.compare(token, options: .caseInsensitive, range: nil, locale: .current) == .orderedSame }) {
                duplicate = index
                continue
            }
            guard validate(token) else { leftovers.append(token); continue }
            next.append(token)
            added.append(token)
        }
        if !added.isEmpty {
            // The new chips are born under the text they were typed as, before the input moves on.
            birth = Birth(point: typedCenter, input: inputFrame)
            withAnimation(motion.snap) { tokens = next }
            announce(added.count == 1 ? "Added \(added[0])" : "Added \(added.count) tokens")
        }
        guard feedback else { return leftovers }
        // A duplicate leaves the input and points at the chip already there, which lifts into its highlight and
        // swells. The field stays still, so only one thing moves.
        if let duplicate {
            selectedID = Self.ids(for: next)[duplicate]
            swell()
            announce("\(next[duplicate]) is already added")
        }
        // Entries kept in the input to fix shake the field once. Reduce Motion has no shake, so the ring dims instead.
        if !leftovers.isEmpty {
            isInvalid = true
            shakeCount += 1
            if reduceMotion { ringBeat += 1 }
            announce(isFull ? "Limit reached" : "Not added: \(leftovers.joined(separator: ", "))")
        }
        // One haptic per commit, on the beat of the shake or the swell: any refusal outranks the additions it came with.
        if duplicate != nil || !leftovers.isEmpty { rejectTick += 1 } else if !added.isEmpty { addTick += 1 }
        return leftovers
    }

    /// First press highlights the last chip, second press removes the highlighted one.
    private func backspaceOnEmpty() {
        guard isEnabled, !tokens.isEmpty else { return }
        if let selectedID, Self.ids(for: tokens).contains(selectedID) {
            remove(id: selectedID)
        } else {
            selectedID = Self.ids(for: tokens).last
            armTick += 1
            announce("\(tokens[tokens.count - 1]) selected. Delete again to remove.")
        }
    }

    private func remove(id: String) {
        guard let index = Self.ids(for: tokens).firstIndex(of: id) else { return }
        let text = tokens[index]
        // The chip leaves the flow at once and melts into the input from where it was, so the rest reflow on their own.
        melt(id, text: text)
        withAnimation(motion.snap) { _ = tokens.remove(at: index) }
        selectedID = nil
        isInvalid = false
        removeTick += 1
        announce("Removed \(text)")
    }

    /// Chips leave and arrive. New ones bud out of the input, born under the text they were typed as (or inside the
    /// input, for a change from outside); removed ones melt back into it.
    private func tokensChanged(from old: [String], to new: [String]) {
        let before = Self.ids(for: old), after = Self.ids(for: new)
        if let selectedID, !after.contains(selectedID) { self.selectedID = nil }
        for (id, text) in zip(before, old) where !after.contains(id) && !melts.contains(where: { $0.token == id }) {
            melt(id, text: text)
        }
        let gone = before.filter { !after.contains($0) }
        if !gone.isEmpty {
            // Their own bubbles have left the flow; this only clears them from the model.
            Task { await buds.gather(gone, reduceMotion: reduceMotion) }
            for id in gone {
                births[id] = nil
                frames[id] = nil
            }
        }
        let added = after.filter { !before.contains($0) }
        guard !added.isEmpty else { return }
        let born = birth ?? Birth(point: CGPoint(x: inputFrame.minX, y: inputFrame.midY), input: inputFrame)
        birth = nil
        for id in added { births[id] = born }
        Task { await buds.bloom(added, reduceMotion: reduceMotion) }
    }

    /// Draws a removed chip where it was and melts it into the input once the flow has laid out without it.
    private func melt(_ id: String, text: String) {
        guard let frame = frames[id] else { return }
        meltCount += 1
        let ghost = Melt(id: "melt\(meltCount)", token: id, text: text, frame: frame, tint: selectedID == id ? style.selection : style.tint(for: text))
        melts.append(ghost)
        buds.place([ghost.id])
        Task {
            // A frame for the flow to settle, so home is where the input now sits.
            try? await Task.sleep(for: .milliseconds(24))
            await buds.gather([ghost.id], reduceMotion: reduceMotion)
            melts.removeAll { $0.id == ghost.id }
        }
    }

    /// A duplicate's swell: out on the tight spring, back on the responsive one.
    private func swell() {
        Task {
            withAnimation(.spring(PieceMotion.tight)) { swellBeat = 1 }
            try? await Task.sleep(for: .milliseconds(100))
            withAnimation(.spring(PieceMotion.responsive)) { swellBeat = 0 }
        }
    }

    private func announce(_ message: String) {
        AccessibilityNotification.Announcement(message).post()
    }
}

// MARK: - Flow layout

/// Marks the subview that fills the rest of its line; the value is its minimum width. `nonisolated` so
/// `FlowLayout` (whose methods are nonisolated) can read it in apps that default to MainActor isolation.
nonisolated private struct FlowFill: LayoutValueKey {
    static let defaultValue: CGFloat? = nil
}

/// Leading-aligned wrapping rows. One pass per call, each subview measured at most twice, so O(n).
///
/// Placement is computed in left-to-right coordinates. For right-to-left layout direction SwiftUI mirrors a
/// custom `Layout`'s placements itself, so this math must not read `layoutDirection` (doing so would flip twice).
private struct FlowLayout: Layout {
    var spacing: CGFloat
    var lineSpacing: CGFloat

    private struct Placement {
        var index: Int
        var origin: CGPoint
        var size: CGSize
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        arrange(width: proposal.width, subviews: subviews).size
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        for placement in arrange(width: bounds.width, subviews: subviews).placements {
            subviews[placement.index].place(
                at: CGPoint(x: bounds.minX + placement.origin.x, y: bounds.minY + placement.origin.y),
                anchor: .topLeading,
                proposal: ProposedViewSize(placement.size)
            )
        }
    }

    /// `width` nil or infinite lays everything out on one line.
    private func arrange(width: CGFloat?, subviews: Subviews) -> (placements: [Placement], size: CGSize) {
        let maxWidth = width.map { max($0, 0) } ?? .infinity
        let tolerance: CGFloat = 0.5
        var placements: [Placement] = []
        placements.reserveCapacity(subviews.count)
        var x: CGFloat = 0, y: CGFloat = 0, rowHeight: CGFloat = 0, rowStart = 0, widest: CGFloat = 0

        func finishRow() {
            guard rowStart < placements.count else { return }
            for i in rowStart..<placements.count {
                placements[i].origin.y = y + (rowHeight - placements[i].size.height) / 2
            }
            widest = max(widest, x - spacing)
            y += rowHeight + lineSpacing
            x = 0
            rowHeight = 0
            rowStart = placements.count
        }

        for (index, subview) in subviews.enumerated() {
            var size: CGSize
            if let minimum = subview[FlowFill.self] {
                let need = min(max(minimum, subview.sizeThatFits(.unspecified).width), maxWidth)
                if x > 0, x + need > maxWidth + tolerance { finishRow() }
                let fill = maxWidth.isFinite ? maxWidth - x : need
                size = CGSize(width: fill, height: subview.sizeThatFits(ProposedViewSize(width: fill, height: nil)).height)
            } else {
                size = subview.sizeThatFits(.unspecified)
                if size.width > maxWidth {
                    size = subview.sizeThatFits(ProposedViewSize(width: maxWidth, height: nil))
                    size.width = min(size.width, maxWidth)
                }
                if x > 0, x + size.width > maxWidth + tolerance { finishRow() }
            }
            placements.append(Placement(index: index, origin: CGPoint(x: x, y: 0), size: size))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        finishRow()
        let height = placements.isEmpty ? 0 : y - lineSpacing
        return (placements, CGSize(width: widest, height: height))
    }
}

// MARK: - Ink press

/// The shared piece press for labels that are only ink: the remove glyph and a suggestion row's text. Under Reduce
/// Motion the press shifts brightness, which near-black or near-white ink can't show, so these also fade while held.
private struct InkPressStyle: ButtonStyle {
    var depth: CGFloat = 2.5
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .opacity(configuration.isPressed && reduceMotion ? 0.5 : 1)
            .piecePress(configuration.isPressed, depth: depth)
    }
}

/// A house-palette color that follows the interface style. The provider is `@Sendable` because SwiftUI
/// resolves colors on its render thread; in an app that defaults to MainActor isolation, a provider that
/// inherited the main actor would trap there.
nonisolated private func adaptive(light: UInt32, dark: UInt32) -> Color {
    Color(uiColor: UIColor { @Sendable traits in
        let hex = traits.userInterfaceStyle == .dark ? dark : light
        return UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    })
}

