    private enum Phase { case presenting, idle, confirming, done, dismissing }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @ScaledMetric(relativeTo: .title) private var titleSize: CGFloat = 26
    @Binding private var isPresented: Bool
    @State private var phase: Phase = .presenting
    @State private var presentTick = 0
    @State private var tileDone = false  // only ever turns on: a beat after the button's check
    @State private var warned = false    // only ever turns on: the destructive warning, once per presentation
    /// The cancel bubble: home inside confirm until the card lands, out below it while the choice is open.
