    private var busy: Bool { phase == .confirming || phase == .done }
    /// The primary's glass: signal on a destructive card, the label color on any other, sage once it is done.
    private var primaryTint: Color { phase == .done ? style.success : (isDestructive ? style.destructive : style.label) }
    private var primaryText: Color { phase == .done || isDestructive ? style.ink : style.onLabel }
