                .accessibilityHidden(true)

            Text(title)
                .font(.system(size: titleSize, weight: .semibold))
                .tracking(-0.6)
                .foregroundStyle(style.label)
                .fixedSize(horizontal: false, vertical: true)
                .padding(.top, 20)
            Text(message)
                .font(.body.weight(.semibold))
                .foregroundStyle(style.secondaryLabel)
                .fixedSize(horizontal: false, vertical: true)
                .padding(.top, 6)

            // Two separate actions, so they rest apart: each its own glass capsule, gooey only while cancel buds out of
            // confirm or melts back into it.
            PieceLiquidGroup {
                VStack(spacing: PieceLiquid.apart) {
                    // Above cancel, so cancel at home sits under it and melts in rather than over its label.
                    primaryButton.zIndex(1)
                    cancelSlot
                }
            }
            .padding(.top, 24)
            // The tint, the glyph and the label all change with the phase.
            .animation(motion.snap, value: phase)
        }
        .padding(.horizontal, 20)
        .padding(.top, 10)
        .padding(.bottom, 20)
        .frame(maxWidth: .infinity)
        .fontWeight(.semibold)
        // The card resolves its geometry as one piece, so its glass leaves with it when the inline card slides away.
        // Without it the budded cancel capsule's glass was left behind for a moment on iOS 26.
        .geometryGroup()
        .sensoryFeedback(.warning, trigger: warned) { _, new in new }
        .sensoryFeedback(.success, trigger: phase) { _, new in new == .done }
        .onAppear { phase = .idle }
        // The tile's bounce, the split and the destructive warning wait for the card to land, so they aren't spent
        // mid-slide. A confirm before then has already played the warning, and leaves cancel inside confirm; after a
        // cancel a warning would contradict the person.
        .task {
            try? await Task.sleep(for: .milliseconds(reduceMotion ? 200 : 300))
            guard !Task.isCancelled, isPresented, phase == .idle else { return }
            presentTick += 1
            warn()
            await buds.bloom(["cancel"], reduceMotion: reduceMotion)
        }
        .accessibilityAddTraits(.isModal)
    }

    /// The primary action on a capsule of glass. While `confirm` runs a spinner sharpens in beside a label that morphs to
    /// Working; when it returns the spinner gives way to a check, the label morphs to Done and the glass turns sage.
    private var primaryButton: some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        return Button(role: isDestructive ? .destructive : nil) {
            guard phase == .idle || phase == .presenting else { return }
            warn()  // a confirm before the card lands still gets its warning, on the tap
            phase = .confirming
            // The choice is made, so cancel melts back into the button that made it.
            if buds.contains("cancel") {
                Task { await buds.gather(["cancel"], reduceMotion: reduceMotion) }
            }
            Task {
                await confirm()
                // The check lands on the button first, under the finger, with the success haptic, and the tile
                // answers a beat later. The beat as a whole is unchanged. The phase stays `.done`, so the card
                // leaves showing its outcome.
                phase = .done
                try? await Task.sleep(for: .milliseconds(80))
                tileDone = true
                try? await Task.sleep(for: .milliseconds(reduceMotion ? 170 : 470))
                isPresented = false
            }
        } label: {
            ZStack {
                // Holds the height at any text size, so the swap never resizes the card or a sheet's detent.
                Text(confirmTitle).hidden()
                HStack(spacing: 8) {
                    switch phase {
                    case .confirming: ProgressView().tint(primaryText).transition(motion.swap)
                    case .done: Image(systemName: "checkmark").transition(motion.swap)
                    default: EmptyView()
                    }
                    ConfirmSheetLabel(text: primaryTitle, font: .headline.weight(.semibold))
                }
            }
            .font(.headline.weight(.semibold))
            .foregroundStyle(primaryText)
            .padding(.horizontal, 20)
            .frame(maxWidth: .infinity, minHeight: 56)
            .contentShape(.capsule)
            .pieceLiquid(.capsule, tint: primaryTint, interactive: false)
        }
        .buttonStyle(PieceLiquidPressStyle())
        .disabled(busy)
        .accessibilityLabel(primaryTitle)
    }

    /// Cancel's place under the primary. It keeps its size while cancel is inside the primary, so the card and a sheet's
    /// detent never change height.
    private var cancelSlot: some View {
        cancelLabel(out: true)
            .hidden()
            .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { cancelHeight = $0 }
            .overlay {
                if buds.contains("cancel") { cancelButton }
            }
    }

    private func cancelLabel(out: Bool) -> some View {
        Text(cancelTitle)
            .font(.headline.weight(.semibold))
            .foregroundStyle(style.label)
            .pieceBudContent(out: out)
            .padding(.horizontal, 20)
            .frame(maxWidth: .infinity, minHeight: 56)
    }

    /// A neutral glass capsule. Home is just inside the primary's lower end, shrunk, where the two are one shape, so it
    /// buds down out of the primary as the card lands and melts back up into it once the choice is made.
    private var cancelButton: some View {
        let out = buds.isOut("cancel")
        return Button {
            guard !busy else { return }
            phase = .dismissing
            isPresented = false
        } label: {
            cancelLabel(out: out)
                .contentShape(.capsule)
                .pieceLiquid(.capsule, interactive: false)
        }
        .buttonStyle(PieceLiquidPressStyle())
        .disabled(busy)
        .pieceBud(out: out, home: CGSize(width: 0, height: -(cancelHeight / 2 + PieceLiquid.apart + cancelHeight * PieceLiquid.homeScale / 2)))
    }

    /// The destructive warning, at most once per presentation.
    private func warn() {
        guard isDestructive, !warned else { return }
        warned = true
    }

    /// Chooses `.sheet` or an inline overlay for the card.
    struct Presenter: ViewModifier {
        @Environment(\.accessibilityReduceMotion) private var reduceMotion
        @Binding var isPresented: Bool
        let inline: Bool
        let style: Style
        let card: ConfirmSheet
        @State private var cardHeight: CGFloat = 320
        @State private var dragOffset: CGFloat = 0
        @State private var pastThreshold = false
        @State private var grabShift: CGFloat?         // the card's pull less the finger's translation; nil between drags
        @State private var homing: Homing?             // the last return home, so a grab can catch the card partway
        @State private var flick: CGFloat = 0          // the card's speed when a drag commits, carried into the exit
        @GestureState private var dragging = false     // resets when the system cancels a touch, which skips onEnded

        /// Past the card's own height, which the move covers: the home indicator and the shadow's reach, so the card
        /// starts and ends fully out of sight and never needs to fade.
        private static let clearance: CGFloat = 64
        /// The rubber band upward, shared by `offset(for:)` and its inverse.
        private static let band = (limit: CGFloat(60), coefficient: CGFloat(0.55))

        /// A return home in flight, so a grab can pick the card up where it is rather than where it is headed.
        private struct Homing {
            var from: CGFloat
            var speed: CGFloat
            var spring: Spring
            var reach: Double  // settle's speed cap, in spring frequencies
            var at: Date

            /// The card's offset at `time` on the curve `settle(velocity:from:to:spring:)` drew, with its speed cap.
            func offset(at time: Date) -> CGFloat {
                let elapsed = time.timeIntervalSince(at)
                guard abs(from) >= 1, elapsed < spring.settlingDuration else { return 0 }
                let cap = 2 * Double.pi / spring.duration * reach
                let relative = CGFloat(min(max(Double(speed / -from), -cap), cap))
                return from + spring.value(target: -from, initialVelocity: relative * -from, time: elapsed)
            }
        }

        func body(content: Content) -> some View {
            if inline {
                let motion = PieceMotion(reduceMotion: reduceMotion)
                content.overlay {
                    ZStack(alignment: .bottom) {
                        if isPresented {
                            // The tray brightens as the card is pulled away from it.
                            Color.black.opacity(0.35 * scrim)
                                .ignoresSafeArea()
                                .onTapGesture { isPresented = false }
                                .transition(.opacity)
                                .accessibilityHidden(true)
                            measured
                                .background(style.surface, in: .rect(cornerRadius: style.cornerRadius, style: .continuous))
                                .shadow(color: .black.opacity(0.22), radius: 34, y: 14)
                                .padding(.horizontal, 10)
                                .padding(.bottom, 10)
                                .offset(y: dragOffset)
                                .gesture(drag)
                                // Without it SwiftUI draws the leaving card under the leaving scrim, so it turns gray as it goes.
                                .zIndex(1)
                                .transition(motion.transition(.move(edge: .bottom).combined(with: .offset(y: Self.clearance))))
                                .onAppear {
                                    dragOffset = 0
                                    flick = 0
                                    grabShift = nil
                                    homing = nil
                                    pastThreshold = false
                                }
                                // A drag the system cancelled (a call, an alert) never ran onEnded, so bring the card home
                                // here. After a normal release onEnded has already sent it home or away.
                                .onChange(of: dragging) { _, isDragging in
                                    if !isDragging, grabShift != nil { letGo(speed: 0) }
                                }
                        }
                    }
                    // Scoped to the tray and card. It arrives calmly and leaves quicker, at the card's speed after a drag.
                    .animation(isPresented ? motion.reveal : exitAnimation(motion), value: isPresented)
                }
                .sensoryFeedback(.impact(flexibility: .rigid), trigger: pastThreshold) { _, past in past }
            } else {
                content.sheet(isPresented: $isPresented) {
                    measured
                        .presentationDetents([.height(cardHeight)])
                        .presentationCornerRadius(style.cornerRadius)
                        .presentationDragIndicator(.hidden)
                        .presentationBackground(style.surface)
                }
            }
        }

        private var measured: some View {
            card.background {
                GeometryReader { proxy in
                    Color.clear
                        .onAppear { cardHeight = proxy.size.height }
                        .onChange(of: proxy.size.height) { _, height in cardHeight = height }
                }
            }
        }

        /// 1 at rest, thinning to 0 as the card is pulled down by its own height.
        private var scrim: Double {
            Double(1 - min(max(dragOffset / max(cardHeight, 1), 0), 1))
        }

        /// The way out. A drag that commits leaves at the card's own speed; a button, the backdrop and the host use the
        /// plain dismiss.
        private func exitAnimation(_ motion: PieceMotion) -> Animation {
            guard !reduceMotion, flick > 0 else { return motion.dismiss }
            // Firm like the dismiss role, with no overshoot at all, started at the flick's speed over the distance the
            // exit transition covers.
            return motion.settle(velocity: flick, from: 0, to: cardHeight + 10 + Self.clearance, spring: Spring(duration: 0.28, bounce: 0))
        }

        /// The card's offset for a vertical drag of `t`: 1:1 downward, rubber-banded upward against its tether.
        private func offset(for t: CGFloat) -> CGFloat {
            PieceMotion.rubberBand(t, in: 0...CGFloat.infinity, limit: Self.band.limit, coefficient: Self.band.coefficient)
        }

        /// The pull that puts the card at `offset`, the inverse of `offset(for:)`, so a grab can take hold anywhere.
        private func translation(for offset: CGFloat) -> CGFloat {
            guard offset < 0 else { return offset }
            let share = min(-offset / Self.band.limit, 0.95)
            return -share / (1 - share) * Self.band.limit / Self.band.coefficient
        }

        /// Downward the card stays under the finger, upward it gives with rubber-band resistance; a flick past the
        /// threshold commits.
        private var drag: some Gesture {
            DragGesture(minimumDistance: 6)
                .updating($dragging) { _, state, _ in state = true }
                .onChanged { value in
                    let t = value.translation.height
                    // The drag takes hold wherever the card is, at rest or partway home from a release, so it never
                    // jumps to meet the finger, not even by the 6pt the gesture waits for. The direct write also stops
                    // a return in flight right there. From then on the card moves with the finger, unanimated.
                    let shift = grabShift ?? translation(for: homing?.offset(at: .now) ?? 0) - t
                    if grabShift == nil {
                        grabShift = shift
                        homing = nil
                    }
                    dragOffset = offset(for: t + shift)
                    // On at the commit line, off only well short of it, so a trembling finger can't repeat the tick.
                    let predicted = value.predictedEndTranslation.height
                    pastThreshold = pastThreshold ? predicted > 60 : predicted > 90
                }
                .onEnded { value in
                    let t = value.translation.height
                    let pull = t + (grabShift ?? 0)
                    // The card's own speed, not the finger's: pulled upward, the band slows it.
                    let speed = (offset(for: pull + value.velocity.height * 0.01) - offset(for: pull)) / 0.01
                    if value.predictedEndTranslation.height > 90 || t > cardHeight * 0.4 {
                        // Only speed toward the exit carries over, so a finger already easing back never lifts the card first.
                        flick = max(speed, 0)
                        grabShift = nil
                        pastThreshold = false
                        isPresented = false
                    } else {
                        letGo(speed: speed)
                    }
                }
        }

        /// The card comes home leaving at `speed` (pt/s). From below it lands on the snap tier with only a small give,
        /// as a weighted card would; pulled up against the tether, it rebounds with more.
        private func letGo(speed: CGFloat) {
            let motion = PieceMotion(reduceMotion: reduceMotion)
            let spring = dragOffset < 0 ? PieceMotion.elastic : PieceMotion.responsive
            // Under Reduce Motion `settle` swaps in its short spring and a lower speed cap, so it can't overshoot; the
            // record follows both, or a quick re-grab would jump to where the card isn't.
            homing = Homing(from: dragOffset, speed: speed, spring: reduceMotion ? Spring(duration: 0.25, bounce: 0) : spring, reach: reduceMotion ? 1 : 1.5, at: .now)
            withAnimation(motion.settle(velocity: speed, from: dragOffset, to: 0, spring: spring)) { dragOffset = 0 }
            grabShift = nil
            pastThreshold = false
        }
    }
}

/// A label that morphs letter by letter when it changes. At accessibility text sizes it is plain text that can wrap,
/// and blurs from the old words to the new instead.
private struct ConfirmSheetLabel: View {
    let text: String
    let font: Font
    @Environment(\.dynamicTypeSize) private var typeSize
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        if typeSize.isAccessibilitySize {
            Text(text)
                .font(font)
                .multilineTextAlignment(.center)
                .id(text)
                .transition(PieceMotion(reduceMotion: reduceMotion).swap)
        } else {
            PieceMorphText(text: text, font: font)
        }
    }
}

/// A house-palette color that follows the interface style.
private func adaptive(light: UInt32, dark: UInt32) -> Color {
    Color(uiColor: UIColor { @Sendable traits in
        let hex = traits.userInterfaceStyle == .dark ? dark : light
        return UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    })
}

