import SwiftUI

/// Presents one transient toast on the top or bottom edge.
///
/// - Parameters:
///   - isPresented: Shows the toast while `true`; the timer, swipe, and action set it back to `false`.
///   - message: Text to show. Keep it to one line.
///   - detail: Optional quieter second line, such as where the item went.
///   - systemImage: Optional SF Symbol; defaults to a symbol that matches `style`.
///   - style: The kind of toast, which picks the tile bubble's tint and default symbol: `.info`, `.success`, `.warning`, or `.error`.
///   - duration: Seconds before it dismisses on its own. The countdown pauses while the toast is touched.
///   - position: `.top` or `.bottom` edge to slide in from.
///   - action: Optional trailing button (for example Undo), a signal glass bubble joined to the card. Tapping it swaps its title for a check, runs the handler, then dismisses a beat later.
///   - appearance: Colors and corner radius. Defaults to the SwiftPieces house palette, adapting to light and dark.
public extension View {
    func toast(isPresented: Binding<Bool>, message: String, detail: String? = nil, systemImage: String? = nil, style: Toast.Style = .info, duration: Double = 3, position: Toast.Position = .top, action: Toast.Action? = nil, appearance: Toast.Appearance = .standard) -> some View {
        modifier(Toast(isPresented: isPresented, message: message, detail: detail, systemImage: systemImage, style: style, duration: duration, position: position, action: action, appearance: appearance))
    }
}

/// Toast modifier. Single instance: presenting again while visible does nothing.
public struct Toast: ViewModifier {
    public enum Style {
        case info, success, warning, error

        var symbol: String {
            switch self {
            case .info: "info"
            case .success: "checkmark"
            case .warning: "exclamationmark"
            case .error: "xmark"
            }
        }
    }

    public enum Position { case top, bottom }

    /// A trailing action such as Undo.
    public struct Action {
        public let title: String
        public let handler: () -> Void

        public init(_ title: String, handler: @escaping () -> Void) {
            self.title = title
            self.handler = handler
        }
    }

    /// Colors and shape. `.standard` is the house palette: a neutral glass card, a tile bubble tinted for its kind (sage
    /// for success, butter for warnings and errors, clear glass for info) and a signal action bubble.
    public struct Appearance: Sendable {
        /// The glass tint of the card. `.clear`, the default, leaves it neutral glass.
        public var surface: Color
        /// Message text, the timer, and the glyph on a clear tile bubble.
        public var label: Color
        /// Detail text.
        public var secondaryLabel: Color
        /// Glyphs and text on tinted bubbles.
        public var ink: Color
        /// The tile bubble's tint for `.info`. `.clear`, the default, leaves it neutral glass.
        public var info: Color
        /// The tile bubble's tint for `.success`.
        public var success: Color
        /// The tile bubble's tint for `.warning`.
        public var warning: Color
        /// The tile bubble's tint for `.error`.
        public var error: Color
        /// The action bubble's tint.
        public var action: Color
        /// Card corner radius.
        public var cornerRadius: CGFloat

        /// Pass only what you want to change; `nil` keeps the house palette value.
        public init(surface: Color? = nil, label: Color? = nil, secondaryLabel: Color? = nil, ink: Color? = nil, info: Color? = nil, success: Color? = nil, warning: Color? = nil, error: Color? = nil, action: Color? = nil, cornerRadius: CGFloat = 22) {
            self.surface = surface ?? .clear
            self.label = label ?? adaptive(light: 0x141414, dark: 0xF4F3EF)
            self.secondaryLabel = secondaryLabel ?? adaptive(light: 0x5C5A56, dark: 0xA6A49F)
            self.ink = ink ?? adaptive(light: 0x141414, dark: 0x141414)
            self.info = info ?? .clear
            self.success = success ?? adaptive(light: 0xA9DCB7, dark: 0xA9DCB7)
            self.warning = warning ?? adaptive(light: 0xFFD976, dark: 0xFFD976)
            self.error = error ?? adaptive(light: 0xFFD976, dark: 0xFFD976)
            self.action = action ?? adaptive(light: 0xFF0000, dark: 0xFF0000)
            self.cornerRadius = cornerRadius
        }

        public static let standard = Appearance()

        func tile(for style: Style) -> Color {
            switch style {
            case .info: info
            case .success: success
            case .warning: warning
            case .error: error
            }
        }
    }

    private enum Phase { case entering, idle, touched, actioned, dismissing }

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Binding private var isPresented: Bool

    @State private var phase: Phase = .entering
    @State private var dragOffset: CGFloat = 0
    @State private var touchPoint: CGPoint?        // where the current touch began, for the press lean
    @State private var grabbedAt: Date?             // when the current touch began, so its first moments ease onto the finger
    @State private var flick: CGFloat = 0           // the card's speed when a swipe commits, carried into the exit
    @State private var travel: CGFloat = 0          // the padded card's height: how far the entrance slides it
    @GestureState private var touching = false      // resets when the system cancels a touch, which skips onEnded
    @State private var elapsed: Double = 0          // countdown consumed before the current run
    @State private var resumedAt: Date = .now       // when the current run started
    @State private var runToken = 0                 // one per run of the countdown; only the latest may dismiss
    @State private var commitTick = 0
    @State private var arriveTick = 0
    @State private var actionTick = 0
    /// The tile and action bubbles: home inside the card's ends until it lands, then out, joined to it.
    @State private var buds = PieceBuds()
    @State private var actionWidth: CGFloat = 0

    private let message: String
    private let detail: String?
    private let systemImage: String?
    private let style: Style
    private let duration: Double
    private let position: Position
    private let action: Action?
    private let appearance: Appearance

    public init(isPresented: Binding<Bool>, message: String, detail: String? = nil, systemImage: String? = nil, style: Style = .info, duration: Double = 3, position: Position = .top, action: Action? = nil, appearance: Appearance = .standard) {
        self._isPresented = isPresented
        self.message = message
        self.detail = detail
        self.systemImage = systemImage
        self.style = style
        self.duration = duration
        self.position = position
        self.action = action
        self.appearance = appearance
    }

    private var edge: Edge { position == .top ? .top : .bottom }

    /// The tile bubble's side, and the height of the action bubble: the house size for round controls.
    private let bubble: CGFloat = 52

    public func body(content: Content) -> some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        content
            .overlay {
                // The reader sits inside the content's safe area, so its insets are whatever the
                // content did not already consume: the Dynamic Island at the top, the keyboard at the bottom.
                GeometryReader { proxy in
                    let exit = exitDistance(in: proxy)
                    ZStack {
                        if isPresented {
                            toast
                                .padding(.top, position == .top ? proxy.safeAreaInsets.top + 8 : 0)
                                .padding(.bottom, position == .bottom ? proxy.safeAreaInsets.bottom + 8 : 0)
                                .padding(.horizontal, 16)
                                // The entrance slides this view in by its own height; the exit starts from it too.
                                .onGeometryChange(for: CGFloat.self) { $0.size.height } action: { travel = $0 }
                                .transition(motion.transition(.asymmetric(
                                    insertion: .move(edge: edge).combined(with: .scale(scale: 0.96, anchor: position == .top ? .top : .bottom)).combined(with: .opacity),
                                    removal: .offset(y: position == .top ? -exit : exit).combined(with: .opacity)
                                )))
                        }
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: position == .top ? .top : .bottom)
                    // Scoped to the toast, so whatever the host changes in the same transaction keeps its own
                    // animation. It arrives calmly and leaves quicker.
                    .animation(isPresented ? motion.reveal : exitAnimation(motion, distance: exit), value: isPresented)
                }
            }
            .sensoryFeedback(.impact(flexibility: .soft), trigger: commitTick)
            .sensoryFeedback(.impact(weight: .light), trigger: actionTick)
            .sensoryFeedback(trigger: arriveTick) { _, _ in
                switch style {
                case .success: .success
                case .warning: .warning
                case .error: .error
                case .info: .impact(flexibility: .soft)
                }
            }
    }

    private var toast: some View {
        // Parts of one control, so the bubbles rest joined to the card and liquid necks hold them to it.
        PieceLiquidGroup {
            HStack(spacing: PieceLiquid.joined) {
                tileSlot
                // Above the bubbles, so one at home sits under the card and melts into it rather than over its text.
                card.zIndex(1)
                if let action { actionSlot(action) }
            }
        }
        .frame(maxWidth: 520)
        .fontWeight(.semibold)
        // Sinks toward the finger while held (dims under Reduce Motion). Before the offset, so it presses the toast
        // where it is and the drag itself is never animated.
        .piecePress(phase == .touched, touch: touchPoint)
        .offset(y: dragOffset)
        .gesture(touchAndSwipe)
        // A touch the system cancelled (a call, an alert, the back swipe) never ran onEnded, so let go here.
        // After a normal release onEnded has already cleared the grab and moved the phase on, so this does nothing.
        .onChange(of: touching) { _, isTouching in
            guard !isTouching else { return }
            grabbedAt = nil
            if phase == .touched { letGo(speed: 0) }
        }
        .task(id: runToken) { await countdown() }
        .task { await land() }
        .onAppear {
            elapsed = 0
            resumedAt = .now
            dragOffset = 0
            flick = 0
            phase = .entering
            buds = PieceBuds()  // this toast's own bubbles, home until it lands
            runToken += 1  // this toast's own countdown, so a timer left over from the last one can't dismiss it
            AccessibilityNotification.Announcement(detail.map { "\(message). \($0)" } ?? message).post()
        }
        .accessibilityElement(children: .contain)
    }

    /// The glass card: the message, an optional detail line and the timer. The words arrive with the card, so they can
    /// be read at once.
    private var card: some View {
        VStack(alignment: .leading, spacing: 1) {
            Text(message)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(appearance.label)
                .lineLimit(2)
            if let detail {
                Text(detail)
                    .font(.footnote.weight(.semibold))
                    .foregroundStyle(appearance.secondaryLabel)
                    .lineLimit(1)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, 16)
        // Tight enough that two lines sit at the bubbles' height: the tile, the card and the action share one height
        // and one centre line, so both necks curve the same way.
        .padding(.vertical, 6)
        .frame(minHeight: bubble)
        .pieceLiquid(RoundedRectangle(cornerRadius: appearance.cornerRadius, style: .continuous), tint: appearance.surface == .clear ? nil : appearance.surface, interactive: false)
        .accessibilityElement(children: .combine)
    }

    /// The tile bubble's place. It keeps its width while the bubble is inside the card, so the card never resizes.
    private var tileSlot: some View {
        Color.clear
            .frame(width: bubble, height: bubble)
            .overlay {
                if buds.contains("tile") { tile }
            }
    }

    /// A round bubble tinted for the kind, with its glyph. Home is just inside the card's leading end, shrunk, where the
    /// two are one shape.
    private var tile: some View {
        let out = buds.isOut("tile")
        let tint = appearance.tile(for: style)
        let clear = tint == .clear
        return ZStack {
            // The time left: a ring around the glyph that drains clockwise from the top.
            timerRing(color: clear ? appearance.label : appearance.ink)
                .padding(5)
            Image(systemName: systemImage ?? style.symbol)
                .font(.body.weight(.semibold))
                .foregroundStyle(clear ? appearance.label : appearance.ink)
        }
            .pieceBudContent(out: out)
            .frame(width: bubble, height: bubble)
            // Its tint drains as it melts, so it never sits colored over the card's words.
            .pieceLiquid(.circle, tint: out && !clear ? tint : nil, interactive: false)
            .pieceBud(out: out, home: CGSize(width: bubble / 2 + PieceLiquid.joined + bubble * PieceLiquid.homeScale / 2, height: 0))
            .accessibilityHidden(true)
    }

    /// The action bubble's place, sized by its title, so the card keeps its width while the bubble is inside it.
    private func actionSlot(_ action: Action) -> some View {
        Text(action.title)
            .font(.subheadline.weight(.semibold))
            .padding(.horizontal, 18)
            .frame(minWidth: 64, minHeight: bubble)
            .hidden()
            .onGeometryChange(for: CGFloat.self) { $0.size.width } action: { actionWidth = $0 }
            .overlay {
                if buds.contains("action") { actionButton(action) }
            }
    }

    /// A signal capsule. Home is just inside the card's trailing end. Tapped, its title blurs into a check and it pops.
    private func actionButton(_ action: Action) -> some View {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        let out = buds.isOut("action")
        return Button {
            guard phase != .actioned, phase != .dismissing else { return }
            withAnimation(motion.snap) { phase = .actioned }
            actionTick += 1
            action.handler()
            runToken += 1  // the countdown now holds the check for a beat, then dismisses
        } label: {
            ZStack {
                // Holds the capsule at the title's width, so the swap never reflows the message.
                Text(action.title).hidden()
                if phase == .actioned {
                    Image(systemName: "checkmark").transition(motion.swap)
                } else {
                    Text(action.title).transition(motion.swap)
                }
            }
            .font(.subheadline.weight(.semibold))
            .foregroundStyle(appearance.ink)
            .pieceBudContent(out: out)
            .padding(.horizontal, 18)
            .frame(minWidth: 64, minHeight: bubble)
            .contentShape(.capsule)
            .pieceLiquid(.capsule, tint: out ? appearance.action : nil, interactive: false)
            .pieceLiquidPop(trigger: actionTick)
        }
        .buttonStyle(.plain)
        .accessibilityLabel(action.title)
        .pieceBud(out: out, home: CGSize(width: -(actionWidth / 2 + PieceLiquid.joined + actionWidth * PieceLiquid.homeScale / 2), height: 0))
    }

    /// The countdown: a ring that drains clockwise from the top, on a faint track. It holds while touched and once
    /// the action has run, and it is a clock, so it keeps running under Reduce Motion.
    private func timerRing(color: Color) -> some View {
        TimelineView(.animation(paused: phase == .touched || phase == .actioned)) { context in
            let consumed = phase == .touched ? elapsed : elapsed + context.date.timeIntervalSince(resumedAt)
            let remaining = max(0, 1 - consumed / duration)
            ZStack {
                Circle().stroke(color.opacity(0.14), lineWidth: 2.5)
                Circle()
                    .trim(from: 0, to: remaining)
                    .stroke(color.opacity(0.62), style: StrokeStyle(lineWidth: 2.5, lineCap: .round))
                    .rotationEffect(.degrees(-90))
            }
        }
        .accessibilityHidden(true)
    }

    /// Dismisses when the time left runs out, or a beat after the action's check appears. Every touch, release,
    /// action and new toast starts a new run, and only the latest run may dismiss.
    private func countdown() async {
        let run = runToken
        switch phase {
        case .touched, .dismissing:
            return
        case .actioned:
            // The handler has run, so this hold always ends in a dismiss, even when the view leaves first and
            // cancels it (the action switched tabs or pushed a screen). A toast that came back with its action live
            // could run the handler twice. Only a newer run (a new toast) takes over.
            try? await Task.sleep(for: .milliseconds(420))
            guard run == runToken else { return }
        case .entering, .idle:
            // Exactly what the bar shows is left.
            try? await Task.sleep(for: .seconds(max(0, duration - elapsed - Date.now.timeIntervalSince(resumedAt))))
            guard !Task.isCancelled, run == runToken else { return }
        }
        dismiss()
    }

    /// The kind's haptic and the bubbles budding out of the card, timed to the card settling rather than the start of
    /// its slide: the tile out of its leading end, then the action out of its trailing end.
    private func land() async {
        try? await Task.sleep(for: .milliseconds(250))
        guard !Task.isCancelled else { return }
        arriveTick += 1
        await buds.bloom(action == nil ? ["tile"] : ["tile", "action"], reduceMotion: reduceMotion)
    }

    private func dismiss() {
        guard phase != .dismissing else { return }
        phase = .dismissing
        isPresented = false
    }

    /// How far the card goes on its way out: until it and its shadow are past the edge, from wherever the drag left it.
    /// At the top the strip between the overlay and the top of the window (the status bar, a navigation bar) is
    /// measured. At the bottom the shadow allowance spans the home indicator, and a tab bar or the keyboard covers the card.
    private func exitDistance(in proxy: GeometryProxy) -> CGFloat {
        let shadowReach: CGFloat = 34  // past the glass's soft lift: its 18-point radius plus its 8-point drop, with room to spare
        let past = position == .top
            ? max(proxy.frame(in: .global).minY, 0) + travel + dragOffset
            : travel - dragOffset
        return max(past + shadowReach, shadowReach)
    }

    /// The way out. A swipe leaves at the card's own speed; the timer, the action and the host use the plain dismiss.
    private func exitAnimation(_ motion: PieceMotion, distance: CGFloat) -> Animation {
        guard !reduceMotion, flick != 0 else { return motion.dismiss }
        // Firm like the dismiss role, with no overshoot at all, started at the flick's speed over the distance the
        // exit covers.
        return motion.settle(velocity: flick, from: 0, to: position == .top ? -distance : distance, spring: Spring(duration: 0.28, bounce: 0))
    }

    /// The card's offset for a vertical drag of `t`: 1:1 toward its edge, rubber-banded away from it.
    private func offset(for t: CGFloat) -> CGFloat {
        let free: ClosedRange<CGFloat> = position == .top ? -CGFloat.infinity...0 : 0...CGFloat.infinity
        return PieceMotion.rubberBand(t, in: free, limit: 60)
    }

    /// One gesture does the pause and the swipe: any touch pauses the countdown and presses the card, which
    /// stays under the finger toward its edge and gives with rubber-band resistance away from it.
    private var touchAndSwipe: some Gesture {
        DragGesture(minimumDistance: 0)
            .updating($touching) { _, state, _ in state = true }
            .onChanged { value in
                if phase == .idle || phase == .entering {
                    elapsed += Date.now.timeIntervalSince(resumedAt)
                    phase = .touched
                    touchPoint = value.startLocation
                    runToken += 1  // stops the running countdown; the release starts one for what is left
                }
                let start = grabbedAt ?? value.time
                grabbedAt = start
                let y = offset(for: value.translation.height)
                // Under the finger. The first 100ms ease onto it on the press spring instead, so a grab while the
                // card is still springing home takes it over from where it is drawn rather than jumping.
                if value.time.timeIntervalSince(start) < 0.1 {
                    withAnimation(PieceMotion(reduceMotion: reduceMotion).press) { dragOffset = y }
                } else {
                    dragOffset = y
                }
            }
            .onEnded { value in
                grabbedAt = nil
                guard phase == .touched else { return }
                let t = value.translation.height
                // The card's own speed, not the finger's: pulled away from the edge, the band slows it.
                let speed = (offset(for: t + value.velocity.height * 0.01) - offset(for: t)) / 0.01
                let away = position == .top ? -value.predictedEndTranslation.height : value.predictedEndTranslation.height
                if away > 40 {
                    // Carried into the exit only toward the edge, so a flick already turning back never dips in first.
                    flick = position == .top ? min(speed, 0) : max(speed, 0)
                    commitTick += 1
                    dismiss()
                } else {
                    letGo(speed: speed)
                }
            }
    }

    /// The touch ends without a swipe, or the system cancels it: the card springs home at `speed` and the
    /// countdown resumes with what is left.
    private func letGo(speed: CGFloat) {
        let motion = PieceMotion(reduceMotion: reduceMotion)
        withAnimation(motion.settle(velocity: speed, from: dragOffset, to: 0)) { dragOffset = 0 }
        phase = .idle
        resumedAt = .now  // before the bar redraws, so it resumes exactly where it froze
        runToken += 1
    }
}

/// A house-palette color that follows the interface style.
private func adaptive(light: UInt32, dark: UInt32) -> Color {
    Color(uiColor: UIColor { @Sendable traits in
        let hex = traits.userInterfaceStyle == .dark ? dark : light
        return UIColor(red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    })
}

